/**
 * Where a new node of `kind` should land, given the current selection.
 *
 * Into the selected container; else alongside the selected node; else the last
 * section — and when the page has no sections at all, at the top level, which
 * is what makes authoring from `emptyDoc()` possible.
 */
export function resolveInsertParent(doc: PageDoc, selectedId: NodeId | null): NodeId | null {
  const selected = selectedId ? doc.nodes[selectedId] : null;
  if (selected) {
    return CONTAINER_TYPES.has(selected.type) ? selected.id : selected.parent;
  }
  return doc.sections[doc.sections.length - 1] ?? null;
}

/**
 * Build the `insert_node` op for adding `kind` to `doc`.
 *
 * Pure — returns the op plus the new id so the caller can select it. Callers
 * apply the op through their own editor state.
 */
export function buildInsertOp(
  doc: PageDoc,
  kind: AddKind,
  selectedId: NodeId | null,
  /** Explicit target, overriding selection — used by drag-and-drop. */
  targetId?: NodeId | null,
): { op: PageOp; id: NodeId } {
  const parent =
    targetId !== undefined
      ? targetId && doc.nodes[targetId]
        ? CONTAINER_TYPES.has(doc.nodes[targetId]!.type)
          ? targetId
          : doc.nodes[targetId]!.parent
        : null
      : resolveInsertParent(doc, selectedId);

  const siblings = childrenOf(doc, parent);
  const order = keyBetween(siblings.length ? siblings[siblings.length - 1]!.order : null, null);
  const id = `n${doc.seq + 1}-${Math.floor(performance.now())}`;
  const def = ADD_DEFAULTS[kind];

  return {
    id,
    op: {
      t: "insert_node",
      node: {
        id,
        type: def.type,
        parent,
        order,
        layout: def.layout,
        props: { ...def.props },
        style: { base: { ...def.style } },
      },
    } as PageOp,
  };
}

/**
 * Editor state engine — pure and framework-agnostic so it's unit-testable.
 * `useEditor` wraps this with `useReducer`. Undo/redo uses document snapshots
 * (simple + robust); the op-level `invert` in the spine is for collab/op-stream
 * undo.
 */
import type { PageDoc } from "../document/types";
import type { PageOp } from "../document/ops";
import { reduce } from "../document/reduce";

export interface EditorState {
  doc: PageDoc;
  past: PageDoc[];
  future: PageDoc[];
  selection: string | null;
}

export type EditorAction =
  | { type: "apply"; op: PageOp }
  | { type: "undo" }
  | { type: "redo" }
  | { type: "select"; id: string | null }
  | { type: "replace"; doc: PageDoc };

const HISTORY_LIMIT = 100;

export function initEditor(doc: PageDoc): EditorState {
  return { doc, past: [], future: [], selection: null };
}

export function editorReduce(state: EditorState, action: EditorAction): EditorState {
  switch (action.type) {
    case "apply": {
      const next = reduce(state.doc, action.op);
      if (next === state.doc) return state; // invalid op → no-op, no history entry
      return {
        ...state,
        doc: next,
        past: [...state.past, state.doc].slice(-HISTORY_LIMIT),
        future: [],
      };
    }
    case "undo": {
      if (state.past.length === 0) return state;
      const prev = state.past[state.past.length - 1]!;
      return {
        ...state,
        doc: prev,
        past: state.past.slice(0, -1),
        future: [state.doc, ...state.future],
      };
    }
    case "redo": {
      if (state.future.length === 0) return state;
      const next = state.future[0]!;
      return {
        ...state,
        doc: next,
        past: [...state.past, state.doc],
        future: state.future.slice(1),
      };
    }
    case "select":
      return state.selection === action.id ? state : { ...state, selection: action.id };
    case "replace":
      return state.doc === action.doc ? state : { ...state, doc: action.doc, future: [] };
    default:
      return state;
  }
}

import { useCallback, useMemo, useReducer } from "react";
import type { PageDoc } from "../document/types";
import type { PageOp } from "../document/ops";
import { editorReduce, initEditor, type EditorState } from "./state";

export interface EditorApi {
  state: EditorState;
  /** Dispatch a mutation through the op-spine (records an undo snapshot). */
  apply: (op: PageOp) => void;
  undo: () => void;
  redo: () => void;
  select: (id: string | null) => void;
  /** Replace the document wholesale (e.g. a controlled `value` change). */
  replace: (doc: PageDoc) => void;
  canUndo: boolean;
  canRedo: boolean;
}

export function useEditor(initialDoc: PageDoc): EditorApi {
  const [state, dispatch] = useReducer(editorReduce, initialDoc, initEditor);
  const apply = useCallback((op: PageOp) => dispatch({ type: "apply", op }), []);
  const undo = useCallback(() => dispatch({ type: "undo" }), []);
  const redo = useCallback(() => dispatch({ type: "redo" }), []);
  const select = useCallback((id: string | null) => dispatch({ type: "select", id }), []);
  const replace = useCallback((doc: PageDoc) => dispatch({ type: "replace", doc }), []);

  return useMemo(
    () => ({
      state,
      apply,
      undo,
      redo,
      select,
      replace,
      canUndo: state.past.length > 0,
      canRedo: state.future.length > 0,
    }),
    [state, apply, undo, redo, select, replace],
  );
}

import { useEffect, useRef, type RefObject } from "react";

/**
 * Hold the latest `value` in a ref, synced in an effect after every render.
 *
 * Notify effects read `ref.current` instead of closing over a callback prop, so
 * their dependency arrays stay data-only (`doc`, `selection`, …). A consumer
 * passing an inline closure — new identity every render, the most natural
 * usage — can then never re-trigger the notify: without this, notify → consumer
 * setState → render → new closure identity → effect re-fires → notify → … loops
 * unbounded (#1). Standard uncontrolled-with-notify hygiene.
 */
export function useLatestRef<T>(value: T): RefObject<T> {
  const ref = useRef(value);
  useEffect(() => {
    ref.current = value;
  });
  return ref;
}

import { Fragment, type ReactElement } from "react";
import type { PageDoc } from "../document/types";
import { emitDocCss } from "../render/css";
import { RenderNode } from "./RenderNode";
import { defaultRegistry, type DataContext, type ElementRegistry } from "./registry";

export interface CmsPageProps {
  doc: PageDoc;
  registry?: ElementRegistry;
  /** Data context that `{ $bind: "…" }` props + repeaters resolve against. */
  data?: DataContext;
  /** Inject the compiled stylesheet. Set false when the host emits CSS itself. */
  includeStyles?: boolean;
}

/** Render a full page document: the compiled stylesheet + every section. */
export function CmsPage({
  doc,
  registry = defaultRegistry,
  data,
  includeStyles = true,
}: CmsPageProps): ReactElement {
  return (
    <Fragment>
      {includeStyles ? <style data-cms-styles="">{emitDocCss(doc)}</style> : null}
      {doc.sections.map((id) => (
        <RenderNode key={id} doc={doc} id={id} registry={registry} data={data} />
      ))}
    </Fragment>
  );
}

import { Fragment, type ReactElement } from "react";
import type { PageDoc } from "../document/types";
import { emitDocCss } from "../render/css";
import { RenderNode } from "./RenderNode";
import { defaultRegistry, type ElementRegistry } from "./registry";

export interface CmsRegionProps {
  doc: PageDoc;
  /** Root node id of the region to render (a section, or any node). */
  root: string;
  registry?: ElementRegistry;
  includeStyles?: boolean;
}

/**
 * Render a single subtree — drop into a hand-coded page so the CMS owns just
 * that region (the "guest, not host" mounting mode). Phase 0/1 emits the whole
 * document's CSS; scoping it to the subtree is a later optimization.
 */
export function CmsRegion({
  doc,
  root,
  registry = defaultRegistry,
  includeStyles = true,
}: CmsRegionProps): ReactElement {
  return (
    <Fragment>
      {includeStyles ? <style data-cms-styles="">{emitDocCss(doc)}</style> : null}
      <RenderNode doc={doc} id={root} registry={registry} />
    </Fragment>
  );
}

import { createContext, useContext } from "react";
import type { CodeEditorContextValue } from "./CodeEditor.types";

export const CodeEditorContext = createContext<CodeEditorContextValue | null>(null);

export function useCodeEditor(): CodeEditorContextValue {
  const ctx = useContext(CodeEditorContext);
  if (!ctx) {
    throw new Error("useCodeEditor must be used within a <CodeEditor> component");
  }
  return ctx;
}

import { useEffect, useMemo, useRef, useState, useCallback } from "react";
import { cn, useControllableState } from "@particle-academy/react-fancy";
import { annotateLines } from "@particle-academy/fancy-file-commons";
import { CodeEditorContext } from "./CodeEditor.context";
import { CodeEditorPanel } from "./CodeEditorPanel";
import { CodeEditorToolbar } from "./CodeEditorToolbar";
import { CodeEditorToolbarSeparator } from "./CodeEditorToolbarSeparator";
import { CodeEditorStatusBar } from "./CodeEditorStatusBar";
import { useEditorEngine } from "../../hooks/use-editor-engine";
import { useDarkMode } from "../../hooks/use-dark-mode";
import { getLanguage } from "../../languages";
import type { CodeEditorProps, CodeEditorContextValue } from "./CodeEditor.types";

function CodeEditorRoot({
  children,
  className,
  value: valueProp,
  defaultValue = "",
  onChange,
  language: languageProp = "javascript",
  onLanguageChange,
  theme = "auto",
  readOnly = false,
  lineNumbers: lineNumbersProp = true,
  wordWrap: wordWrapProp = false,
  tabSize: tabSizeProp = 2,
  placeholder,
  minHeight,
  maxHeight,
  cursorLine,
  cursorColumn,
  diffBase,
}: CodeEditorProps) {
  const [currentValue, setCurrentValue] = useControllableState(valueProp, defaultValue, onChange);

  // Diff gutter: per-line change marks of the current value vs the baseline.
  // Line-level only (no intra-line segmentation), recomputed as the user types.
  const diffAnnotations = useMemo(
    () => (diffBase == null ? null : annotateLines(diffBase, currentValue)),
    [diffBase, currentValue],
  );

  // Reactive dark mode for "auto" theme
  const isDark = useDarkMode();
  const resolvedTheme = theme === "auto" ? (isDark ? "dark" : "light") : theme;

  // Language state (changeable via toolbar selector)
  const [currentLanguage, setCurrentLanguageState] = useState(() => {
    const def = getLanguage(languageProp);
    return def?.name ?? languageProp;
  });

  const setLanguage = useCallback(
    (lang: string) => {
      const def = getLanguage(lang);
      const resolved = def?.name ?? lang;
      setCurrentLanguageState(resolved);
      onLanguageChange?.(resolved);
    },
    [onLanguageChange],
  );

  // Toggle states
  const [showLineNumbers, setShowLineNumbers] = useState(lineNumbersProp);
  const [isWordWrap, setIsWordWrap] = useState(wordWrapProp);

  // Cursor position
  const [cursorPosition, setCursorPosition] = useState({ line: 1, col: 1 });
  const [selectionLength, setSelectionLength] = useState(0);

  const containerRef = useRef<HTMLDivElement>(null);

  // Our custom editor engine
  const engineReturn = useEditorEngine({
    containerRef,
    value: currentValue,
    onChange: setCurrentValue,
    language: currentLanguage,
    theme: resolvedTheme,
    readOnly,
    lineNumbers: showLineNumbers,
    wordWrap: isWordWrap,
    tabSize: tabSizeProp,
    placeholder,
    minHeight,
    maxHeight,
    onCursorChange: ({ line, col, selectionLength: sel }) => {
      setCursorPosition({ line, col });
      setSelectionLength(sel);
    },
  });

  // Reveal + place the caret when cursorLine/cursorColumn change (and on mount).
  // revealLine is stable, so this fires only on target change; it runs after the
  // engine's value-sync effect, so the textarea is populated and sized first.
  const { revealLine: revealLineImpl } = engineReturn;
  useEffect(() => {
    if (cursorLine == null) return;
    revealLineImpl(cursorLine, cursorColumn ?? 1, { focus: false });
  }, [cursorLine, cursorColumn, revealLineImpl]);

  const contextValue = useMemo<CodeEditorContextValue>(
    () => ({
      getValue: () => engineReturn.textareaRef.current?.value ?? currentValue,
      getSelection: () => {
        const ta = engineReturn.textareaRef.current;
        if (!ta) return "";
        return ta.value.slice(ta.selectionStart, ta.selectionEnd);
      },
      setValue: (v: string) => setCurrentValue(v),
      replaceSelection: (text: string) => {
        const ta = engineReturn.textareaRef.current;
        if (!ta) return;
        const start = ta.selectionStart;
        const end = ta.selectionEnd;
        const before = ta.value.slice(0, start);
        const after = ta.value.slice(end);
        ta.value = before + text + after;
        ta.selectionStart = ta.selectionEnd = start + text.length;
        setCurrentValue(ta.value);
      },
      focus: () => engineReturn.textareaRef.current?.focus(),
      revealLine: (line: number, column?: number) =>
        engineReturn.revealLine(line, column ?? 1, { focus: true }),
      setCursor: ({ line, column }: { line: number; column?: number }) =>
        engineReturn.revealLine(line, column ?? 1, { focus: true }),
      language: currentLanguage,
      setLanguage,
      theme: resolvedTheme,
      readOnly,
      lineNumbers: showLineNumbers,
      wordWrap: isWordWrap,
      tabSize: tabSizeProp,
      toggleWordWrap: () => setIsWordWrap((w) => !w),
      toggleLineNumbers: () => setShowLineNumbers((l) => !l),
      copyToClipboard: async () => {
        const text = engineReturn.textareaRef.current?.value ?? currentValue;
        await navigator.clipboard.writeText(text);
      },
      cursorPosition,
      selectionLength,
      textareaRef: engineReturn.textareaRef,
      placeholder,
      diffStats: diffAnnotations
        ? {
            added: diffAnnotations.added,
            modified: diffAnnotations.modified,
            removed: diffAnnotations.removed,
          }
        : null,
      _diffAnnotations: diffAnnotations,
      _engineReturn: engineReturn,
      _minHeight: minHeight,
      _maxHeight: maxHeight,
    }),
    [engineReturn, currentValue, currentLanguage, setLanguage, resolvedTheme, readOnly, showLineNumbers, isWordWrap, tabSizeProp, cursorPosition, selectionLength, setCurrentValue, placeholder, diffAnnotations, minHeight, maxHeight],
  );

  return (
    <CodeEditorContext.Provider value={contextValue}>
      <div
        data-fancy-code-editor=""
        className={cn(
          "overflow-hidden",
          className,
        )}
      >
        {children}
      </div>
    </CodeEditorContext.Provider>
  );
}

CodeEditorRoot.displayName = "CodeEditor";

const ToolbarWithSeparator = Object.assign(CodeEditorToolbar, {
  Separator: CodeEditorToolbarSeparator,
});

export const CodeEditor = Object.assign(CodeEditorRoot, {
  Toolbar: ToolbarWithSeparator,
  Panel: CodeEditorPanel,
  StatusBar: CodeEditorStatusBar,
});

import type { ReactNode, RefObject } from "react";
import type { DiffAnnotations } from "@particle-academy/fancy-file-commons";
import type { UseEditorEngineReturn } from "../../hooks/use-editor-engine";

export interface CodeEditorProps {
  children: ReactNode;
  className?: string;
  /** Controlled value */
  value?: string;
  /** Initial value (uncontrolled) */
  defaultValue?: string;
  /** Called when the document changes */
  onChange?: (value: string) => void;
  /** Language name or alias (default: "javascript") */
  language?: string;
  /** Called when the language changes via the toolbar selector */
  onLanguageChange?: (lang: string) => void;
  /** Theme name: "light", "dark", "auto", or a custom registered name (default: "auto") */
  theme?: string;
  /** Prevent editing (default: false) */
  readOnly?: boolean;
  /** Show line numbers (default: true) */
  lineNumbers?: boolean;
  /** Enable word wrap (default: false) */
  wordWrap?: boolean;
  /** Tab size in spaces (default: 2) */
  tabSize?: number;
  /** Placeholder shown when empty */
  placeholder?: string;
  /** Minimum height in px */
  minHeight?: number;
  /** Maximum height in px (scrolls beyond this) */
  maxHeight?: number;
  /**
   * 1-based line to reveal (scroll to + place the caret on). Applied on mount
   * and whenever it (or `cursorColumn`) changes — so opening a file *at* a line,
   * or re-targeting an already-open file, scrolls the line into view. Does not
   * steal focus; call the imperative `revealLine`/`setCursor` (or `focus`) for
   * that. Out-of-range values clamp to document bounds.
   */
  cursorLine?: number;
  /** 1-based column for {@link cursorLine} (default 1). */
  cursorColumn?: number;
  /**
   * Baseline document for the diff gutter. When set, the line-number column
   * shows per-line change marks of the CURRENT value against this baseline —
   * VS Code convention: a green bar for added lines, a blue bar for modified
   * lines, and a red wedge where lines were deleted. Recomputed live as the
   * user types (line-level only — cheap). `null`/omitted disables the gutter
   * marks. Requires `lineNumbers`.
   */
  diffBase?: string | null;
}

export interface CodeEditorContextValue {
  /** Get the current document text */
  getValue: () => string;
  /** Get the currently selected text */
  getSelection: () => string;
  /** Replace the entire document */
  setValue: (value: string) => void;
  /** Replace the current selection */
  replaceSelection: (text: string) => void;
  /** Focus the editor */
  focus: () => void;
  /**
   * Scroll to + place the caret on a 1-based `line` (optional 1-based `column`),
   * focusing the editor. Out-of-range positions clamp to document bounds.
   */
  revealLine: (line: number, column?: number) => void;
  /** Place the caret at a 1-based `{ line, column }` and reveal it (focuses). */
  setCursor: (pos: { line: number; column?: number }) => void;
  /** Current language name */
  language: string;
  /** Change the active language */
  setLanguage: (lang: string) => void;
  /** Current theme name */
  theme: string;
  /** Whether the editor is read-only */
  readOnly: boolean;
  /** Whether line numbers are shown */
  lineNumbers: boolean;
  /** Whether word wrap is enabled */
  wordWrap: boolean;
  /** Current tab size */
  tabSize: number;
  /** Toggle word wrap on/off */
  toggleWordWrap: () => void;
  /** Toggle line numbers on/off */
  toggleLineNumbers: () => void;
  /** Copy entire document to clipboard */
  copyToClipboard: () => Promise<void>;
  /** Current cursor position */
  cursorPosition: { line: number; col: number };
  /** Length of the current selection (0 if none) */
  selectionLength: number;
  /**
   * Ref to the underlying `<textarea>` element. Exposed so external
   * widgets — e.g. `<InputTag>`'s `textareaAdapter` — can attach to
   * the same input the editor renders into. Will be `null` before
   * the editor has mounted.
   */
  textareaRef: RefObject<HTMLTextAreaElement | null>;
  /** Placeholder text */
  placeholder?: string;
  /**
   * Totals of the live diff against {@link CodeEditorProps.diffBase} —
   * `{ added, modified, removed }` — or `null` when no baseline is set.
   * Handy for a status-bar chip or a host's save indicator.
   */
  diffStats: { added: number; modified: number; removed: number } | null;
  /** @internal — per-line gutter annotations for the diff marks. */
  _diffAnnotations: DiffAnnotations | null;
  /** @internal */
  _engineReturn: UseEditorEngineReturn | null;
  /** @internal */
  _minHeight?: number;
  /** @internal */
  _maxHeight?: number;
}

export interface CodeEditorToolbarProps {
  children?: ReactNode;
  className?: string;
}

export interface CodeEditorPanelProps {
  className?: string;
}

export interface CodeEditorStatusBarProps {
  children?: ReactNode;
  className?: string;
}

import { useMemo } from "react";
import { cn } from "@particle-academy/react-fancy";
import { useCodeEditor } from "./CodeEditor.context";
import {
  diffMarkColor,
  diffRemovedColor,
  gutterDiffMark,
  hasDeletedAtEnd,
} from "./diff-gutter";
import type { CodeEditorPanelProps } from "./CodeEditor.types";

export function CodeEditorPanel({ className }: CodeEditorPanelProps) {
  const {
    _engineReturn: engine,
    lineNumbers,
    wordWrap,
    readOnly,
    placeholder,
    _diffAnnotations: diffAnnotations,
    _maxHeight,
    _minHeight,
  } = useCodeEditor();

  // This `useMemo` MUST run before the `!engine` guard below it.
  //
  // The guard used to come first, so a render without an engine ran ZERO hooks
  // and the next one ran one. React compares hook counts between renders, so
  // that transition desyncs the hook order and throws from deep inside React,
  // naming none of this code. `_engineReturn` is typed `| null` and starts null,
  // so the transition is real rather than theoretical.
  //
  // Reading the engine's fields inside the callback (rather than destructuring
  // above) is what lets the hook run unconditionally.
  const lineNumberElements = useMemo(() => {
    if (!engine || !lineNumbers) return null;
    const { themeColors, lineCount, activeLine } = engine;
    const removed = diffRemovedColor(themeColors);
    const lines = [];
    for (let i = 1; i <= lineCount; i++) {
      const mark = gutterDiffMark(diffAnnotations, i);
      lines.push(
        <div
          key={i}
          data-diff={mark?.type}
          data-diff-deleted-above={mark?.deletedAbove ? "" : undefined}
          style={{
            position: "relative",
            color: i === activeLine ? themeColors.foreground : themeColors.gutterForeground,
            backgroundColor: i === activeLine ? themeColors.activeLineBackground : undefined,
          }}
          className="pr-3 text-right text-[13px] leading-[1.5] select-none"
        >
          {/* Change bar — VS Code convention: green added, blue modified. */}
          {mark?.type && (
            <span
              aria-hidden="true"
              style={{
                position: "absolute",
                left: 0,
                top: 0,
                bottom: 0,
                width: 3,
                borderRadius: 2,
                backgroundColor: diffMarkColor(mark.type, themeColors),
              }}
            />
          )}
          {/* Deletion wedge — lines were removed immediately above this one. */}
          {mark?.deletedAbove && (
            <span
              aria-hidden="true"
              style={{
                position: "absolute",
                left: 0,
                top: -4,
                width: 0,
                height: 0,
                borderLeft: `8px solid ${removed}`,
                borderTop: "4px solid transparent",
                borderBottom: "4px solid transparent",
              }}
            />
          )}
          {i}
          {/* Deletion at EOF — removed lines hang below the last line. */}
          {i === lineCount && hasDeletedAtEnd(diffAnnotations) && (
            <span
              aria-hidden="true"
              data-diff-deleted-at-end=""
              style={{
                position: "absolute",
                left: 0,
                bottom: -4,
                width: 0,
                height: 0,
                borderLeft: `8px solid ${removed}`,
                borderTop: "4px solid transparent",
                borderBottom: "4px solid transparent",
              }}
            />
          )}
        </div>,
      );
    }
    return lines;
  }, [engine, lineNumbers, diffAnnotations]);

  // Every hook is above this line.
  if (!engine) return null;

  const {
    textareaRef,
    highlightedHtml,
    lineCount,
    activeLine,
    themeColors,
    handleKeyDown,
    handleInput,
    handleScroll,
    handleSelect,
    scrollTop,
    scrollLeft,
  } = engine;

  const gutterWidth = lineNumbers ? `${Math.max(String(lineCount).length, 2) * 0.75 + 1.5}em` : "0";

  const containerStyle: React.CSSProperties = {
    backgroundColor: themeColors.background,
    color: themeColors.foreground,
    minHeight: _minHeight,
    maxHeight: _maxHeight,
  };

  const isEmpty = textareaRef.current ? textareaRef.current.value.length === 0 : highlightedHtml.length === 0;

  return (
    <div
      data-fancy-code-panel=""
      className={cn("relative overflow-auto", className)}
      style={containerStyle}
    >
      <div className="flex min-h-full">
        {/* Line numbers gutter */}
        {lineNumbers && (
          <div
            className="sticky left-0 z-10 shrink-0 pt-2.5 pb-2.5 pl-2"
            style={{
              backgroundColor: themeColors.gutterBackground,
              borderRight: `1px solid ${themeColors.gutterBorder}`,
              width: gutterWidth,
            }}
          >
            {lineNumberElements}
          </div>
        )}

        {/* Editor area */}
        <div className={cn("relative flex-1", wordWrap && "min-w-0")}>
          {/* Highlighted code overlay */}
          <pre
            className="pointer-events-none absolute inset-0 m-0 overflow-hidden border-none p-2.5 text-[13px] leading-[1.5]"
            aria-hidden="true"
            style={{
              whiteSpace: wordWrap ? "pre-wrap" : "pre",
              overflowWrap: wordWrap ? "break-word" : "normal",
            }}
          >
            <code dangerouslySetInnerHTML={{ __html: highlightedHtml + "\n" }} />
          </pre>

          {/* Placeholder */}
          {placeholder && isEmpty && (
            <div
              className="pointer-events-none absolute left-0 top-0 p-2.5 text-[13px] leading-[1.5] opacity-40"
              style={{ color: themeColors.foreground }}
            >
              {placeholder}
            </div>
          )}

          {/* Actual textarea for input */}
          <textarea
            ref={textareaRef}
            className={cn(
              "relative m-0 block resize-none border-none bg-transparent p-2.5 text-[13px] leading-[1.5] text-transparent outline-none",
              wordWrap ? "w-full" : "min-w-full",
            )}
            style={{
              caretColor: themeColors.cursorColor,
              minHeight: _minHeight ? _minHeight - 40 : 80,
              overflow: "hidden",
              whiteSpace: wordWrap ? "pre-wrap" : "pre",
              overflowWrap: wordWrap ? "break-word" : "normal",
            }}
            spellCheck={false}
            autoComplete="off"
            autoCorrect="off"
            autoCapitalize="off"
            readOnly={readOnly}
            onKeyDown={handleKeyDown}
            onInput={handleInput}
            onScroll={handleScroll}
            onSelect={handleSelect}
            onClick={handleSelect}
          />
        </div>
      </div>
    </div>
  );
}

