    if (closeTimer.current) clearTimeout(closeTimer.current);
    closeTimer.current = setTimeout(() => {
      if (activeRef.current === id) setActiveSub(null);
    }, 150);
  }, [id, setActiveSub]);

  const cancelClose = useCallback(() => {
    if (closeTimer.current) { clearTimeout(closeTimer.current); closeTimer.current = null; }
  }, []);

  useEffect(() => () => {
    if (closeTimer.current) clearTimeout(closeTimer.current);
  }, []);

  return (
    <div
      className="relative"
      onMouseEnter={cancelClose}
      onMouseLeave={scheduleClose}
      data-react-fancy-context-menu-sub=""
    >
      <ContextMenuSubContext.Provider value={{ open, setOpen, cancelClose }}>
        {children}
      </ContextMenuSubContext.Provider>
    </div>
  );
}

ContextMenuSub.displayName = "ContextMenuSub";

export function ContextMenuSubTrigger({ children, className }: ContextMenuSubTriggerProps) {
  const { open, setOpen, cancelClose } = useContext(ContextMenuSubContext);

  return (
    <button
      type="button"
      data-react-fancy-context-menu-sub-trigger=""
      role="menuitem"
      aria-haspopup="menu"
      aria-expanded={open}
      className={cn(
        "flex w-full items-center justify-between rounded-lg px-3 py-2 text-left text-sm transition-colors",
        "text-zinc-700 hover:bg-zinc-100 dark:text-zinc-300 dark:hover:bg-zinc-800",
        open && "bg-zinc-100 dark:bg-zinc-800",
        className,
      )}
      onMouseEnter={() => {
        cancelClose();
        setOpen(true);
      }}
      onClick={() => setOpen(!open)}
    >
      <span>{children}</span>
      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="ml-2 opacity-50">
        <polyline points="9 18 15 12 9 6" />
      </svg>
    </button>
  );
}

ContextMenuSubTrigger.displayName = "ContextMenuSubTrigger";

export function ContextMenuSubContent({ children, className }: ContextMenuSubContentProps) {
  const { open } = useContext(ContextMenuSubContext);
  const ref = useRef<HTMLDivElement>(null);
  const [flipLeft, setFlipLeft] = useState(false);
  const [topOffset, setTopOffset] = useState(0);
  const [maxH, setMaxH] = useState<number | undefined>(undefined);

  useEffect(() => {
    if (!open || !ref.current) return;
    const pad = 8;
    const rect = ref.current.getBoundingClientRect();

    // Horizontal: flip left if overflowing right
    setFlipLeft(rect.right > window.innerWidth - pad);

    // Vertical: shift up if overflowing bottom, cap height if still too tall
    const overflow = rect.bottom - (window.innerHeight - pad);
    if (overflow > 0) {
      const shifted = Math.min(overflow, rect.top - pad);
      setTopOffset(-shifted);
      if (overflow > shifted) {
        setMaxH(window.innerHeight - pad * 2);
      } else {
        setMaxH(undefined);
      }
    } else {
      setTopOffset(0);
      setMaxH(undefined);
    }
  }, [open]);

  if (!open) return null;

  return (
    <div
      ref={ref}
      data-react-fancy-context-menu-sub-content=""
      role="menu"
      className={cn(
        "absolute z-50 min-w-[8rem] rounded-xl border border-zinc-200 bg-white p-1 shadow-lg dark:border-zinc-700 dark:bg-zinc-900",
        flipLeft ? "right-full mr-1" : "left-full ml-1",
        maxH && "overflow-y-auto",
        className,
      )}
      style={{ top: topOffset, maxHeight: maxH }}
    >
      <MenuGroupProvider>
        {children}
      </MenuGroupProvider>
    </div>
  );
}

