import { type ReactNode } from "react";
import type { Deck, DeckOp, SlideElement, Theme } from "../../types";
import { type IdStrategy } from "../../hooks/use-deck-state";
import { type ToolbarApi } from "../EditorToolbar";
import { DeckEditorProvider } from "./DeckEditorProvider";
import {
    DeckEditorCanvas,
    DeckEditorInspector,
    DeckEditorNotes,
    DeckEditorRail,
    DeckEditorStatusBar,
    DeckEditorToolbar,
} from "./slots";

export interface DeckEditorProps {
    /** Controlled deck — pair with `onChange`. */
    value: Deck;
    onChange: (next: Deck) => void;
    /** Called after every mutation with the op that produced it — feed into AgentPanel / audit log. */
    onOp?: (op: DeckOp) => void;
    /** Called when the user clicks Present. The host decides how to open the SlideViewer. */
    onPresent?: () => void;
    /** Controlled selected slide id. Uncontrolled by default. */
    selectedSlideId?: string | null;
    onSelectedSlideChange?: (id: string | null) => void;
    /**
     * Renderer for chart / code / table / embed elements (the elements this
     * package doesn't render natively). Defaults to the built-in
     * `defaultElementRegistry` so the editor is full out of the box; pass your
     * own to override (it wins entirely). The optional-peer hosts (chart/code)
     * load fancy-echarts/fancy-code via guarded dynamic imports, so the base
     * bundle never statically requires them.
     */
    renderElement?: (element: SlideElement, slideWidthPx: number) => ReactNode | undefined;
    /** Hide the slide rail (e.g. for embedded use). */
    hideRail?: boolean;
    /** Hide the speaker notes panel. */
    hideNotes?: boolean;
    /** Hide the toolbar. */
    hideToolbar?: boolean;
    /** Hide the inspector. */
    hideInspector?: boolean;
    /** Optional extra content on the toolbar's trailing edge. */
    toolbarExtra?: ReactNode;
    /**
     * Theme list the toolbar's picker offers. Defaults to the built-in themes;
     * pass user-authored themes (`[...builtinThemes, myTheme]`) to extend it.
     */
    themes?: Theme[];
    /** Who mints new slide/element ids. Defaults to `"client"`. See {@link IdStrategy}. */
    idStrategy?: IdStrategy;
    /**
     * Compose the toolbar yourself. Receives the toolbar action surface and
     * returns the toolbar node — typically built from `EditorToolbar` + its slot
     * components (`.Title` / `.Insert` / `.Themes` / `.Trailing`). When omitted,
     * the default toolbar is rendered.
     */
    renderToolbar?: (api: ToolbarApi) => ReactNode;
    className?: string;
}

/**
 * Full deck editor — toolbar + rail + canvas + inspector + speaker notes.
 *
 * Controlled (`value` + `onChange`). State is intentionally simple: deck
 * lives in the consumer, the editor just renders a view + dispatches ops.
 * The same `DeckOp` enum that the agent bridge speaks runs through here —
 * agents and humans drive identical mutations.
 *
 * This is the **default layout** over a shared controller. To build a bespoke
 * editor — reposition panels, drop an app panel *beside* them, restyle each —
 * compose the parts yourself: `<DeckEditor.Provider>` runs the controller, and
 * `DeckEditor.Toolbar` / `.Rail` / `.Canvas` / `.Inspector` / `.Notes` /
 * `.StatusBar` are slots that share it (selection included). `useDeckEditor()`
 * exposes the same controller to any panel of your own.
 */
export function DeckEditor({
    value,
    onChange,
    onOp,
    onPresent,
    selectedSlideId,
    onSelectedSlideChange,
    renderElement,
    hideRail = false,
    hideNotes = false,
    hideToolbar = false,
    hideInspector = false,
    toolbarExtra,
    themes,
    idStrategy = "client",
    renderToolbar,
    className,
}: DeckEditorProps) {
    return (
        <DeckEditorProvider
            value={value}
            onChange={onChange}
            onOp={onOp}
            onPresent={onPresent}
            selectedSlideId={selectedSlideId}
            onSelectedSlideChange={onSelectedSlideChange}
            renderElement={renderElement}
            themes={themes}
            idStrategy={idStrategy}
        >
            <div
                className={`fs-editor flex h-full w-full flex-col bg-zinc-100 dark:bg-zinc-950 ${className ?? ""}`}
                data-fancy-slides-editor={value.id}
            >
                {!hideToolbar && <DeckEditorToolbar renderToolbar={renderToolbar} extra={toolbarExtra} />}

                <div className="flex min-h-0 flex-1">
                    {!hideRail && <DeckEditorRail />}

                    <div className="flex min-w-0 flex-1 flex-col">
                        <DeckEditorCanvas />
                        {!hideNotes && <DeckEditorNotes />}
                    </div>

                    {!hideInspector && <DeckEditorInspector />}
                </div>
            </div>
        </DeckEditorProvider>
    );
}

// Compound slot statics — match the house style (direct assignment, like
// EditorToolbar.Title) so consumers compose `<DeckEditor.Provider>` +
// `<DeckEditor.Rail>` etc.
DeckEditor.Provider = DeckEditorProvider;
DeckEditor.Toolbar = DeckEditorToolbar;
DeckEditor.Rail = DeckEditorRail;
DeckEditor.Canvas = DeckEditorCanvas;
DeckEditor.Inspector = DeckEditorInspector;
DeckEditor.Notes = DeckEditorNotes;
DeckEditor.StatusBar = DeckEditorStatusBar;

import { useCallback, useEffect, useMemo, useState, type ReactNode } from "react";
import type {
    ChartElement,
    CodeElement,
    Deck,
    DeckOp,
    ImageElement,
    ShapeElement,
    ShapeKind,
    Slide as SlideData,
    SlideElement,
    TableElement,
    TextElement,
    Theme,
} from "../../types";
import { resolveTheme } from "../../theme/theme-utils";
import { builtinThemes } from "../../theme/default-theme";
import { elementId } from "../../utils/ids";
import { useDeckState, type IdStrategy } from "../../hooks/use-deck-state";
import { migrateDeck } from "../../utils/serialize";
import { chartStarterOption, type ChartKind } from "../../utils/chart-presets";
import { type ToolbarApi } from "../EditorToolbar";
import { defaultElementRegistry } from "../../registry";
import { DeckEditorContext, type DeckEditorContextValue } from "./context";

export interface DeckEditorProviderProps {
    /** Controlled deck — pair with `onChange`. */
    value: Deck;
    onChange: (next: Deck) => void;
    /** Called after every mutation with the op that produced it — feed into AgentPanel / audit log. */
    onOp?: (op: DeckOp) => void;
    /** Called when the user clicks Present. The host decides how to open the SlideViewer. */
    onPresent?: () => void;
    /** Controlled selected slide id. Uncontrolled by default. */
    selectedSlideId?: string | null;
    onSelectedSlideChange?: (id: string | null) => void;
    /**
     * Renderer for chart / code / table / embed elements. Defaults to the
     * built-in `defaultElementRegistry`; pass your own to override (it wins
     * entirely).
     */
    renderElement?: (element: SlideElement, slideWidthPx: number) => ReactNode | undefined;
    /**
     * Theme list the toolbar's picker offers. Defaults to the built-in themes;
     * pass user-authored themes (`[...builtinThemes, myTheme]`) to extend it.
     */
    themes?: Theme[];
    /** Who mints new slide/element ids. Defaults to `"client"`. See {@link IdStrategy}. */
    idStrategy?: IdStrategy;
    /** The composed editor — `DeckEditor.*` slots plus any app chrome. */
    children: ReactNode;
}

/**
 * Runs the editor controller — op surface, slide + element selection, insert
 * handlers, the toolbar action surface — and provides it to every
 * `DeckEditor.*` slot via {@link useDeckEditor}. `<DeckEditor>` mounts this for
 * you with its default layout; mount it yourself to compose a bespoke editor
 * from the slot parts (and your own panels) sharing one controller.
 *
 * Controlled (`value` + `onChange`). The same `DeckOp` enum the agent bridge
 * speaks runs through here — agents and humans drive identical mutations.
 */
export function DeckEditorProvider({
    value,
    onChange,
    onOp,
    onPresent,
    selectedSlideId: controlledSlideId,
    onSelectedSlideChange,
    renderElement = defaultElementRegistry,
    themes,
    idStrategy = "client",
    children,
}: DeckEditorProviderProps) {
    const deck = value;
    const ops = useDeckState({ value: deck, onChange, onOp, idStrategy });

    // Migrate an older-schema deck forward on load and emit one normalized
    // onChange so the consumer can persist the upgraded shape. migrateDeck is
    // idempotent (returns the same ref once current), so this won't loop. Keyed
    // on deck id: a freshly-loaded deck re-runs the migration.
    useEffect(() => {
        const migrated = migrateDeck(value);
        if (migrated !== value) onChange(migrated);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [value.id]);

    // Slide selection — controlled or internal.
    const [internalSlideId, setInternalSlideId] = useState<string | null>(deck.slides[0]?.id ?? null);
    const isControlled = controlledSlideId !== undefined;
    const slideId = isControlled ? controlledSlideId! : internalSlideId;
    const setSlideId = useCallback(
        (id: string | null) => {
            if (!isControlled) setInternalSlideId(id);
            onSelectedSlideChange?.(id);
        },
        [isControlled, onSelectedSlideChange],
    );

    // If the selected slide disappears (deletion / agent ops), fall back to the first slide.
    useEffect(() => {
        if (slideId && !deck.slides.some((s) => s.id === slideId)) {
            setSlideId(deck.slides[0]?.id ?? null);
        } else if (!slideId && deck.slides.length > 0) {
            setSlideId(deck.slides[0]!.id);
        }
    }, [deck.slides, slideId, setSlideId]);

    const slide: SlideData | undefined = deck.slides.find((s) => s.id === slideId);

    // Element selection — internal, resets on slide change.
    const [elementIdSelected, setElementIdSelected] = useState<string | null>(null);
    useEffect(() => {
        setElementIdSelected(null);
    }, [slideId]);

    const selectedElement = slide && elementIdSelected ? slide.elements.find((e) => e.id === elementIdSelected) ?? null : null;

    // ─── Toolbar insert handlers ───────────────────────────────────────────
    const insertEl = useCallback(
        (element: Omit<SlideElement, "id">) => {
            if (!slide) return;
            const id = ops.addElement(slide.id, { id: elementId(), ...element });
            setElementIdSelected(id);
        },
        [slide, ops],
    );

    const insertText = useCallback(
        () =>
            insertEl({
                type: "text",
                x: 0.1,
                y: 0.4,
                w: 0.8,
                h: 0.2,
                content: "Click to edit",
                format: "plain",
                style: { fontSize: 36, weight: "semibold", align: "center" },
            } as Omit<TextElement, "id">),
        [insertEl],
    );

    const insertImage = useCallback(
        () =>
            insertEl({
                type: "image",
                x: 0.25,
                y: 0.25,
                w: 0.5,
                h: 0.5,
                src: "https://placehold.co/600x400?text=Image",
                fit: "contain",
            } as Omit<ImageElement, "id">),
        [insertEl],
    );

    const insertShape = useCallback(
        (shape: ShapeKind) =>
            insertEl({
                type: "shape",
                shape,
                x: 0.3,
                y: 0.3,
                w: 0.4,
                h: 0.4,
                fill: shape === "line" || shape === "arrow" ? "none" : "rgba(139,92,246,0.15)",
                stroke: "#8b5cf6",
                strokeWidth: 2,
            } as Omit<ShapeElement, "id">),
        [insertEl],
    );

    const insertChart = useCallback(
        (kind: ChartKind = "bar") =>
            insertEl({
                type: "chart",
                x: 0.1,
                y: 0.2,
                w: 0.8,
                h: 0.6,
                option: chartStarterOption(kind),
            } as Omit<ChartElement, "id">),
        [insertEl],
    );

    const insertCode = useCallback(
        () =>
            insertEl({
                type: "code",
                x: 0.15,
                y: 0.2,
                w: 0.7,
                h: 0.6,
                code: "function hello() {\n  return \"world\";\n}\n",
                language: "typescript",
                codeTheme: "dark",
            } as Omit<CodeElement, "id">),
        [insertEl],
    );

    const insertTable = useCallback(
        () =>
            insertEl({
                type: "table",
                x: 0.15,
                y: 0.25,
                w: 0.7,
                h: 0.5,
                columns: [
                    { key: "name", label: "Name" },
                    { key: "value", label: "Value" },
                ],
                rows: [
                    { name: "Alpha", value: 12 },
                    { name: "Beta", value: 34 },
                    { name: "Gamma", value: 56 },
                ],
            } as Omit<TableElement, "id">),
        [insertEl],
    );

    const insert = useMemo<DeckEditorContextValue["insert"]>(
        () => ({ text: insertText, image: insertImage, shape: insertShape, chart: insertChart, code: insertCode, table: insertTable }),
        [insertText, insertImage, insertShape, insertChart, insertCode, insertTable],
    );

    const themeList = themes ?? Object.values(builtinThemes);

    // The toolbar action surface — handed to a custom `renderToolbar`, and the
    // source for the default toolbar too.
    const toolbarApi: ToolbarApi = useMemo(
        () => ({
            title: { value: deck.title, onChange: (t) => ops.setTitle(t) },
            theme: { name: deck.theme.name, themes: themeList, onApply: (t) => ops.applyTheme(t) },
            insert,
            present: onPresent,
            disabled: !slide,
        }),
        [deck.title, deck.theme.name, themeList, ops, insert, onPresent, slide],
    );

    const ctx = useMemo<DeckEditorContextValue>(
        () => ({
            deck,
            theme: resolveTheme(deck.theme),
            ops,
            slideId,
            setSlideId,
            slide,
            selectedElementId: elementIdSelected,
            setSelectedElementId: setElementIdSelected,
            selectedElement,
            insert,
            toolbarApi,
            renderElement,
            themes: themeList,
            onPresent,
        }),
        [deck, ops, slideId, setSlideId, slide, elementIdSelected, selectedElement, insert, toolbarApi, renderElement, themeList, onPresent],
    );

    return <DeckEditorContext.Provider value={ctx}>{children}</DeckEditorContext.Provider>;
}

import { createContext, useContext, type ReactNode } from "react";
import type { Deck, ShapeKind, Slide as SlideData, SlideElement, Theme } from "../../types";
import type { DeckStateApi } from "../../hooks/use-deck-state";
import type { ChartKind, ToolbarApi } from "../EditorToolbar";

/**
 * The editor's insert action surface — one entry per element type the toolbar
 * can add. Each inserts a starter element on the active slide and selects it.
 */
export interface DeckEditorInsertApi {
    text(): void;
    image(): void;
    shape(kind: ShapeKind): void;
    chart(kind?: ChartKind): void;
    code(): void;
    table(): void;
}

/**
 * The shared editor controller — everything a slot part needs to render itself
 * and drive the deck. Provided by {@link DeckEditorProvider} (and therefore by
 * `<DeckEditor>` itself), read by every `DeckEditor.*` slot via
 * {@link useDeckEditor}. Selection lives here, so all slots — and any app panel
 * the host drops alongside them — share one controller rather than re-deriving
 * their own.
 */
export interface DeckEditorContextValue {
    /** The controlled deck (== the provider's `value`). */
    deck: Deck;
    /** Resolved theme (`resolveTheme(deck.theme)`) — defaults filled in. */
    theme: Theme;
    /** The op surface from `useDeckState`. */
    ops: DeckStateApi;
    /** Currently-selected slide id. */
    slideId: string | null;
    setSlideId: (id: string | null) => void;
    /** The currently-selected slide, if any. */
    slide: SlideData | undefined;
    /** Currently-selected element id (shared across slots — the crux of #11). */
    selectedElementId: string | null;
    setSelectedElementId: (id: string | null) => void;
    /** The currently-selected element, if any. */
    selectedElement: SlideElement | null;
    /** Insert handlers — add a starter element of each type to the active slide. */
    insert: DeckEditorInsertApi;
    /** The toolbar action surface (title / theme / insert / present / disabled). */
    toolbarApi: ToolbarApi;
    /** Renderer for chart / code / table / embed elements. */
    renderElement: (element: SlideElement, slideWidthPx: number) => ReactNode | undefined;
    /** The theme list the picker offers (defaults to the built-ins). */
    themes: Theme[];
    /** Present handler, if the host wired one. */
    onPresent?: () => void;
}

export const DeckEditorContext = createContext<DeckEditorContextValue | null>(null);

/**
 * Read the shared editor controller. Must be called inside a
 * `<DeckEditor.Provider>` (which `<DeckEditor>` mounts for you) — throws a clear
 * error otherwise, mirroring `EditorToolbar`'s slot guard.
 */
export function useDeckEditor(): DeckEditorContextValue {
    const ctx = useContext(DeckEditorContext);
    if (!ctx) {
        throw new Error("useDeckEditor() (and DeckEditor.* slots) must be used inside <DeckEditor.Provider> (mounted for you by <DeckEditor>).");
    }
    return ctx;
}

export { DeckEditor } from "./DeckEditor";
export type { DeckEditorProps } from "./DeckEditor";

export { DeckEditorProvider } from "./DeckEditorProvider";
export type { DeckEditorProviderProps } from "./DeckEditorProvider";

export { useDeckEditor, DeckEditorContext } from "./context";
export type { DeckEditorContextValue, DeckEditorInsertApi } from "./context";

export {
    DeckEditorToolbar,
    DeckEditorRail,
    DeckEditorCanvas,
    DeckEditorInspector,
    DeckEditorNotes,
    DeckEditorStatusBar,
} from "./slots";
export type {
    DeckEditorToolbarProps,
    DeckEditorRailProps,
    DeckEditorCanvasProps,
    DeckEditorInspectorProps,
    DeckEditorNotesProps,
    DeckEditorStatusBarProps,
} from "./slots";

import { type CSSProperties, type ReactNode } from "react";
import type { SlideElement, TextElement } from "../../types";
import { Slide } from "../Slide";
import { SlideRail } from "../SlideRail";
import { EditorToolbar, type ToolbarApi } from "../EditorToolbar";
import { ElementInspector } from "../ElementInspector";
import { SpeakerNotes } from "../SpeakerNotes";
import { useDeckEditor } from "./context";

export interface DeckEditorToolbarProps {
    className?: string;
    /**
     * Compose the toolbar yourself. Receives the toolbar action surface and
     * returns the toolbar node. When omitted, the default `EditorToolbar` is
     * rendered.
     */
    renderToolbar?: (api: ToolbarApi) => ReactNode;
    /** Extra content on the toolbar's trailing edge (default toolbar only). */
    extra?: ReactNode;
}

/**
 * The editor toolbar, wired to the shared controller. Renders the default
 * `EditorToolbar` from the `toolbarApi`, or your `renderToolbar(api)` node.
 */
export function DeckEditorToolbar({ className, renderToolbar, extra }: DeckEditorToolbarProps) {
    const { toolbarApi, deck, ops, themes } = useDeckEditor();
    if (renderToolbar) {
        return <>{renderToolbar(toolbarApi)}</>;
    }
    const bar = (
        <EditorToolbar
            title={deck.title}
            onTitleChange={(t) => ops.setTitle(t)}
            themeName={deck.theme.name}
            onApplyTheme={(t) => ops.applyTheme(t)}
            themes={themes}
            onInsertText={toolbarApi.insert.text}
            onInsertImage={toolbarApi.insert.image}
            onInsertShape={toolbarApi.insert.shape}
            onInsertChart={toolbarApi.insert.chart}
            onInsertCode={toolbarApi.insert.code}
            onInsertTable={toolbarApi.insert.table}
            onPresent={toolbarApi.present}
            disabled={toolbarApi.disabled}
            toolbarExtra={extra}
        />
    );
    // Keep the default layout's DOM byte-identical: wrap only when a className
    // is supplied (bespoke composition), otherwise render the bar bare.
    return className ? <div className={className}>{bar}</div> : bar;
}

export interface DeckEditorRailProps {
    className?: string;
    style?: CSSProperties;
}

/** The slide rail — thumbnails, add / duplicate / remove / reorder, selection. */
export function DeckEditorRail({ className, style }: DeckEditorRailProps) {
    const { deck, ops, slideId, setSlideId, renderElement } = useDeckEditor();
    return (
        <div
            className={`w-56 shrink-0 overflow-y-auto border-r border-zinc-200 bg-white dark:border-zinc-800 dark:bg-zinc-950${className ? ` ${className}` : ""}`}
            style={style}
        >
            <SlideRail
                slides={deck.slides}
                selectedId={slideId}
                theme={deck.theme}
                onSelect={setSlideId}
                onAdd={(after) => {
                    const id = ops.addSlide(after !== undefined ? after : deck.slides.length);
                    setSlideId(id);
                }}
                onDuplicate={(id) => {
                    const newId = ops.duplicateSlide(id);
                    setSlideId(newId);
                }}
                onRemove={(id) => ops.removeSlide(id)}
                onReorder={(id, toIndex) => ops.reorderSlide(id, toIndex)}
                renderElement={renderElement}
            />
        </div>
    );
}

export interface DeckEditorCanvasProps {
    className?: string;
    style?: CSSProperties;
}

/** The centered, editable slide canvas (drag / resize / inline-edit). */
export function DeckEditorCanvas({ className, style }: DeckEditorCanvasProps) {
    const { deck, theme, slide, ops, selectedElementId, setSelectedElementId, renderElement } = useDeckEditor();
    return (
        <div className={`flex flex-1 items-center justify-center overflow-auto p-6${className ? ` ${className}` : ""}`} style={style}>
            {slide ? (
                <div
                    className="rounded-lg shadow-xl"
                    style={{
                        width: "min(96%, 1280px)",
                        aspectRatio: String(theme.aspectRatio ?? 16 / 9),
                        background: "white",
                    }}
                >
                    <Slide
                        slide={slide}
                        theme={deck.theme}
                        editing
                        onElementContentChange={(eid, content) => ops.updateElement(slide.id, eid, { content, format: "markdown" } as Partial<TextElement>)}
                        onElementSelect={setSelectedElementId}
                        selectedElementId={selectedElementId}
                        onElementMove={(eid, x, y) => ops.moveElement(slide.id, eid, x, y)}
                        onElementResize={(eid, patch) => ops.updateElement(slide.id, eid, patch as Partial<SlideElement>)}
                        renderElement={renderElement}
                    />
                </div>
            ) : (
                <div className="grid place-items-center rounded-lg border border-dashed border-zinc-300 bg-white px-12 py-24 text-sm text-zinc-500 dark:border-zinc-700 dark:bg-zinc-950">
                    Add a slide to start editing.
                </div>
            )}
        </div>
    );
}

export interface DeckEditorInspectorProps {
    className?: string;
    style?: CSSProperties;
}

/** The right-hand element / slide inspector. */
export function DeckEditorInspector({ className, style }: DeckEditorInspectorProps) {
    const { slide, ops, selectedElement, selectedElementId, setSelectedElementId } = useDeckEditor();
    return (
        <div className={`w-72 shrink-0 overflow-y-auto${className ? ` ${className}` : ""}`} style={style}>
            <ElementInspector
                element={selectedElement}
                slide={slide ?? null}
                onPatch={(patch) => slide && selectedElementId && ops.updateElement(slide.id, selectedElementId, patch)}
                onDelete={() => {
                    if (!slide || !selectedElementId) return;
                    ops.removeElement(slide.id, selectedElementId);
                    setSelectedElementId(null);
                }}
                onLockToggle={(locked) => slide && selectedElementId && ops.updateElement(slide.id, selectedElementId, { locked } as Partial<SlideElement>)}
                onSetTransition={(transition) => slide && ops.setTransition(slide.id, transition)}
                onSetBackground={(background) => slide && ops.setBackground(slide.id, background)}
                onSetLayout={(layout) => slide && ops.setLayout(slide.id, layout)}
                onSetAnimation={(animation) => slide && selectedElementId && ops.setAnimation(slide.id, selectedElementId, animation)}
                onSetElementAnimation={(eid, animation) => slide && ops.setAnimation(slide.id, eid, animation)}
            />
        </div>
    );
}

export interface DeckEditorNotesProps {
    className?: string;
    placeholder?: string;
}

/** Speaker notes for the active slide. Renders nothing when no slide is selected. */
export function DeckEditorNotes({ className, placeholder }: DeckEditorNotesProps) {
    const { slide, ops } = useDeckEditor();
    if (!slide) return null;
    const notes = <SpeakerNotes notes={slide.notes} onChange={(n) => ops.setNotes(slide.id, n)} placeholder={placeholder} />;
    // Match the default layout: render bare unless a className wrapper is asked for.
    return className ? <div className={className}>{notes}</div> : notes;
}

export interface DeckEditorStatusBarProps {
    className?: string;
    style?: CSSProperties;
    /** Custom content. Receives the shared controller for a bespoke bar. */
    children?: ReactNode | ((ctx: ReturnType<typeof useDeckEditor>) => ReactNode);
}

/**
 * A status bar summarizing the current slide + selection. Not part of the
 * default `<DeckEditor>` layout — drop it into a bespoke composition. Pass
 * `children` (node or render-prop) to replace the default summary entirely.
 */
export function DeckEditorStatusBar({ className, style, children }: DeckEditorStatusBarProps) {
    const ctx = useDeckEditor();
    const { deck, slideId, slide, selectedElement } = ctx;
    const cls = `fs-statusbar flex items-center gap-3 border-t border-zinc-200 bg-white px-4 py-1.5 text-xs text-zinc-500 dark:border-zinc-800 dark:bg-zinc-950${className ? ` ${className}` : ""}`;

    if (children !== undefined) {
        return (
            <div className={cls} style={style}>
                {typeof children === "function" ? children(ctx) : children}
            </div>
        );
    }

    const index = slideId ? deck.slides.findIndex((s) => s.id === slideId) : -1;
    const pct = (n: number) => `${Math.round(n * 100)}%`;
    return (
        <div className={cls} style={style}>
            <span>{slide ? `Slide ${index + 1}/${deck.slides.length}` : `${deck.slides.length} slide${deck.slides.length === 1 ? "" : "s"}`}</span>
            {selectedElement && (
                <>
                    <span className="text-zinc-300 dark:text-zinc-700">·</span>
                    <span className="font-mono">{selectedElement.type}</span>
                    <span className="font-mono">
                        x {pct(selectedElement.x)} · y {pct(selectedElement.y)} · w {pct(selectedElement.w)} · h {pct(selectedElement.h)}
                    </span>
                </>
            )}
        </div>
    );
}

import { useMemo } from "react";
import {
  fileLabel,
  parseUnifiedDiff,
  type AcceptanceState,
  type AcceptanceStatus,
  type Diff,
  type DiffLine,
  type Hunk,
} from "@particle-academy/fancy-file-commons";

/**
 * A git diff, on the suite's shared diff model.
 *
 * ## Why it takes a patch string
 *
 * `fancy-git` hands back `Diff { patch, files }` — a unified diff. This used to
 * take a bespoke `DiffFile[]` instead, so every consumer had to write their own
 * unified-diff parser to get from what git returns to what the viewer renders.
 * `parseUnifiedDiff` already exists and is already the parser fancy-diff and
 * fancy-code use, so the patch goes straight in.
 *
 * ## Why the model is fancy-file-commons'
 *
 * This component used to declare its own `DiffLine` / `DiffFile`, so a `Diff`
 * produced by fancy-diff could not be handed to it and vice versa — two diff
 * models in one suite, and this was the poorer of the two: no word-level
 * segmentation, no stable content-derived hunk ids, and acceptance expressed as
 * a bare `string[]` of selected ids, which cannot say *rejected*.
 */
export interface DiffViewerProps {
  /**
   * A unified diff, or already-parsed files.
   *
   * The string form is what `fancy-git`'s `Diff.patch` carries. Pass parsed
   * `Diff[]` when the caller already has them — from `computeDiff`, or from one
   * parse shared with another surface.
   */
  value: string | Diff[];
  /**
   * Per-hunk accept / reject / pending. Controlled.
   *
   * A hunk with no entry is `pending`. That is not the same as rejected, and
   * conflating them is what the old `selectedHunkIds: string[]` did: an id was
   * either in the list or absent, so "not looked at yet" and "explicitly turned
   * down" were one state, and a review could not tell whether it was finished.
   */
  acceptance?: AcceptanceState;
  onAcceptanceChange?: (next: AcceptanceState) => void;
  /** `split` renders before and after side by side. */
  mode?: "unified" | "split";
  onModeChange?: (mode: "unified" | "split") => void;
  /** Hide `equal` hunks — the context lines git includes around each change. */
  hideContext?: boolean;
  className?: string;
}

/** Cycles pending → accepted → rejected → pending, so one control reaches all three. */
function nextStatus(current: AcceptanceStatus): AcceptanceStatus {
  return current === "pending" ? "accepted" : current === "accepted" ? "rejected" : "pending";
}

export function DiffViewer({
  value,
  acceptance = {},
  onAcceptanceChange,
  mode = "unified",
  onModeChange,
  hideContext = false,
  className,
}: DiffViewerProps) {
  // Parsing is the expensive part, and a patch does not change between renders.
  const files = useMemo(() => (typeof value === "string" ? parseUnifiedDiff(value) : value), [value]);

  const toggle = (hunkId: string) =>
    onAcceptanceChange?.({ ...acceptance, [hunkId]: nextStatus(acceptance[hunkId] ?? "pending") });

  return (
    <section className={className} data-git-diff="" data-git-diff-mode={mode} aria-label="Git diff">
      <header>
        <strong>Changes</strong>
        <button
          type="button"
          data-git-diff-mode-toggle=""
          onClick={() => onModeChange?.(mode === "unified" ? "split" : "unified")}
        >
          {mode}
        </button>
      </header>

      {files.length === 0 && <p data-git-diff-empty="">No changes</p>}

      {files.map((file, index) => (
        <FileDiff
          // `fileLabel` is undefined for a diff with no header — a computed
          // diff rather than a parsed patch — so the index carries it.
          key={fileLabel(file.file) ?? index}
          file={file}
          acceptance={acceptance}
          onToggle={onAcceptanceChange ? toggle : undefined}
          mode={mode}
          hideContext={hideContext}
        />
      ))}
    </section>
  );
}

function FileDiff({
  file,
  acceptance,
  onToggle,
  mode,
  hideContext,
}: {
  file: Diff;
  acceptance: AcceptanceState;
  onToggle?: (hunkId: string) => void;
  mode: "unified" | "split";
  hideContext: boolean;
}) {
  const path = fileLabel(file.file) ?? "(no path)";
  const hunks = hideContext ? file.hunks.filter((hunk) => hunk.type !== "equal") : file.hunks;

  return (
    <article data-git-diff-file={path}>
      <h3>{path}</h3>
      {file.file?.partial && (
        // A unified diff carries only the changed hunks plus a little context,
        // never the whole file. Saying so stops a reader taking a line's
        // absence as evidence it is not in the file.
        <p data-git-diff-partial="">Showing changed regions only</p>
      )}
      {hunks.map((hunk) => (
        <HunkView
          key={hunk.id}
          hunk={hunk}
          status={acceptance[hunk.id] ?? "pending"}
          onToggle={onToggle}
          mode={mode}
        />
      ))}
    </article>
  );
}

function HunkView({
  hunk,
  status,
  onToggle,
  mode,
}: {
  hunk: Hunk;
  status: AcceptanceStatus;
  onToggle?: (hunkId: string) => void;
  mode: "unified" | "split";
}) {
  // Equal hunks are context, not proposals — there is nothing to accept, and a
  // control implies there is.
  const reviewable = hunk.type !== "equal" && onToggle !== undefined;

  return (
    <div data-git-hunk={hunk.id} data-hunk-type={hunk.type} data-hunk-status={status}>
      {reviewable && (
        <button
          type="button"
          data-git-hunk-toggle={hunk.id}
          aria-pressed={status === "accepted"}
          aria-label={`${status} — ${hunk.type} hunk`}
          onClick={() => onToggle(hunk.id)}
        >
          {status}
        </button>
      )}
      {mode === "split" ? <SplitLines hunk={hunk} /> : <UnifiedLines hunk={hunk} />}
    </div>
  );
}

function UnifiedLines({ hunk }: { hunk: Hunk }) {
  return (
    <pre data-git-diff-lines="unified">
      {hunk.lines.map((line, index) => (
        <Line key={index} line={line} />
      ))}
    </pre>
  );
}

/**
 * Before and after, side by side.
 *
 * The old component had a `split` mode that was a data attribute and a toggle
 * button with nothing behind it — the markup was identical either way, so the
 * control changed a label and no output.
 *
 * Rows pair by position within each side rather than by line number: a
 * `replace` hunk's removals and additions correspond in order, and the line
 * numbers diverge exactly where the file changed, which is every row here.
 */
function SplitLines({ hunk }: { hunk: Hunk }) {
  const before = hunk.lines.filter((line) => line.side !== "after");
  const after = hunk.lines.filter((line) => line.side !== "before");
  const rows = Math.max(before.length, after.length);

  return (
    <div data-git-diff-lines="split">
      <pre data-git-diff-side="before">
        {Array.from({ length: rows }, (_, index) =>
          before[index] ? (
            <Line key={index} line={before[index]} side="before" />
          ) : (
            // A pad, not an omission: without it the two columns drift out of
            // alignment and a removal stops lining up with what replaced it.
            <span key={index} data-git-diff-pad="" />
          ),
        )}
      </pre>
      <pre data-git-diff-side="after">
        {Array.from({ length: rows }, (_, index) =>
          after[index] ? <Line key={index} line={after[index]} side="after" /> : <span key={index} data-git-diff-pad="" />,
        )}
      </pre>
    </div>
  );
}

function Line({ line, side }: { line: DiffLine; side?: "before" | "after" }) {
  // On a split side one number is meaningful; in unified mode both are shown,
  // which is what makes it unified.
  const shown = side === "before" ? line.beforeLineNo : side === "after" ? line.afterLineNo : undefined;

  return (
    <span data-git-diff-line={line.side} data-kind={kindOf(line)}>
      {side ? (
        <span data-git-line-no="">{shown ?? " "}</span>
      ) : (
        <>
          <span data-git-line-no="before">{line.beforeLineNo ?? " "}</span>
          <span data-git-line-no="after">{line.afterLineNo ?? " "}</span>
        </>
      )}
      <code>{line.text}</code>
    </span>
  );
}

/** The +/-/context a reader expects, derived rather than stored a second time. */
function kindOf(line: DiffLine): "addition" | "deletion" | "context" {
  return line.side === "after" ? "addition" : line.side === "before" ? "deletion" : "context";
}

import { useState, type ComponentProps, type ReactNode } from "react";
import { cn, Badge } from "@particle-academy/react-fancy";
import type { DownlineEdge, DownlineMember } from "./types";
import { buildDownline, type DownlineNode } from "./tree";

type BadgeColor = ComponentProps<typeof Badge>["color"];

export interface DownlineTreeProps<T extends DownlineMember = DownlineMember> {
  /** Flat member list (controlled). Linked into a tree by `edge`. */
  value: T[];
  /**
   * Which pointer links the tree — `"sponsor"` (unilevel, default) or
   * `"placement"` (binary / matrix). The same `value` renders every tree shape.
   */
  edge?: DownlineEdge;
  /** Render only this member's subtree. */
  rootId?: string | null;
  /** Highlight a member (controlled selection). */
  selectedId?: string | null;
  onSelect?: (id: string, member: T) => void;
  /** Map a tier to a react-fancy Badge color. */
  tierColor?: (tier: string | undefined) => BadgeColor;
  /** Replace the default member row content. */
  renderMember?: (member: T, node: DownlineNode<T>) => ReactNode;
  className?: string;
}

/**
 * Genealogy / downline tree. Controlled `value`, stable `data-mlm-node` handles
 * on every member, controlled selection, and JSON-friendly inputs — an agent can
 * read the tree and drive selection without scraping the DOM.
 */
export function DownlineTree<T extends DownlineMember = DownlineMember>({
  value,
  edge = "sponsor",
  rootId,
  selectedId,
  onSelect,
  tierColor,
  renderMember,
  className,
}: DownlineTreeProps<T>) {
  const forest = buildDownline(value, rootId, edge);

  return (
    <div data-fancy-mlm="downline-tree" data-mlm-edge={edge} className={cn("fancy-mlm-tree", className)}>
      <ul className="fancy-mlm-tree__list" role="tree">
        {forest.map((node) => (
          <DownlineNodeView
            key={node.member.id}
            node={node}
            selectedId={selectedId}
            onSelect={onSelect}
            tierColor={tierColor}
            renderMember={renderMember}
          />
        ))}
      </ul>
    </div>
  );
}

function DownlineNodeView<T extends DownlineMember>({
  node,
  selectedId,
  onSelect,
  tierColor,
  renderMember,
}: {
  node: DownlineNode<T>;
  selectedId?: string | null;
  onSelect?: (id: string, member: T) => void;
  tierColor?: (tier: string | undefined) => BadgeColor;
  renderMember?: (member: T, node: DownlineNode<T>) => ReactNode;
}) {
  const [expanded, setExpanded] = useState(true);
  const { member, children } = node;
  const hasChildren = children.length > 0;
  const active = member.active ?? true;

  return (
    <li className="fancy-mlm-tree__item" data-mlm-node={member.id} role="treeitem" aria-expanded={hasChildren ? expanded : undefined}>
      <div
        className={cn(
          "fancy-mlm-tree__row",
          selectedId === member.id && "is-selected",
          !active && "is-inactive",
        )}
      >
        {hasChildren ? (
          <button
            type="button"
            className="fancy-mlm-tree__toggle"
            aria-label={expanded ? "Collapse" : "Expand"}
            aria-expanded={expanded}
            onClick={() => setExpanded((value) => !value)}
          >
            {expanded ? "▾" : "▸"}
          </button>
        ) : (
          <span className="fancy-mlm-tree__toggle fancy-mlm-tree__toggle--leaf" aria-hidden="true" />
        )}

        <button
          type="button"
          className="fancy-mlm-tree__label"
          data-mlm-member={member.id}
          onClick={() => onSelect?.(member.id, member)}
        >
          {renderMember ? (
            renderMember(member, node)
          ) : (
            <>
              <span className="fancy-mlm-tree__name">{member.label ?? member.id}</span>
              {member.tier ? (
                <Badge color={tierColor?.(member.tier)} variant="soft">
                  {member.tier}
                </Badge>
              ) : null}
              {!active ? <span className="fancy-mlm-tree__muted">inactive</span> : null}
            </>
          )}
        </button>
      </div>

      {hasChildren && expanded ? (
        <ul className="fancy-mlm-tree__list" role="group">
          {children.map((child) => (
            <DownlineNodeView
              key={child.member.id}
              node={child}
              selectedId={selectedId}
              onSelect={onSelect}
              tierColor={tierColor}
              renderMember={renderMember}
            />
          ))}
        </ul>
      ) : null}
    </li>
  );
}

import { createContext, useContext } from "react";
import type { DrawerContextValue } from "./Drawer.types";

export const DrawerContext = createContext<DrawerContextValue | null>(null);

export function useDrawer(): DrawerContextValue {
  const ctx = useContext(DrawerContext);
  if (!ctx) {
    throw new Error("Drawer compound components must be used within <Drawer>");
  }
  return ctx;
}

import { useCallback, useEffect, useMemo, useRef } from "react";
import { cn } from "../../utils/cn";
import { Portal } from "../Portal";
import { DrawerContext } from "./Drawer.context";
import { DrawerHeader } from "./DrawerHeader";
import { DrawerBody } from "./DrawerBody";
import { DrawerFooter } from "./DrawerFooter";
import { DrawerContainer } from "./DrawerContainer";
import { useFocusTrap } from "../../hooks/use-focus-trap";
import { useEscapeKey } from "../../hooks/use-escape-key";
import { useAnimation } from "../../hooks/use-animation";
import type { DrawerProps, DrawerSide } from "./Drawer.types";

/**
 * `size` addresses the drawer's own axis: width on the horizontal edges,
 * height on the vertical ones. Keeping one scale across both means `size="lg"`
 * does not have to be re-learned when a drawer moves from the side to the
 * bottom.
 */
const WIDTH = {
  sm: "w-64",
  md: "w-80",
  lg: "w-96",
  xl: "w-[32rem]",
  full: "w-full",
} as const;

const HEIGHT = {
  sm: "h-32",
  md: "h-64",
  lg: "h-96",
  xl: "h-[32rem]",
  full: "h-full",
} as const;

const ANCHOR: Record<DrawerSide, string> = {
  left: "inset-y-0 left-0",
  right: "inset-y-0 right-0",
  top: "inset-x-0 top-0",
  bottom: "inset-x-0 bottom-0",
};

const ENTER: Record<DrawerSide, string> = {
  left: "fancy-slide-in-left",
  right: "fancy-slide-in-right",
  top: "fancy-slide-in-top",
  bottom: "fancy-slide-in-bottom",
};

const EXIT: Record<DrawerSide, string> = {
  left: "fancy-slide-out-left",
  right: "fancy-slide-out-right",
  top: "fancy-slide-out-top",
  bottom: "fancy-slide-out-bottom",
};

/** The panel's edge shadow reads as depth away from the anchored edge. */
const EDGE: Record<DrawerSide, string> = {
  left: "border-r",
  right: "border-l",
  top: "border-b",
  bottom: "border-t",
};

function DrawerRoot({
  children,
  open,
  onClose,
  side = "right",
  size = "md",
  attach = "viewport",
  backdrop = true,
  dismissOnBackdrop = true,
  dismissOnEscape = true,
  className,
  ...rest
}: DrawerProps) {
  const panelRef = useRef<HTMLDivElement>(null);
  const horizontal = side === "left" || side === "right";
  const isViewport = attach === "viewport";

  const close = useCallback(() => onClose(), [onClose]);
  useEscapeKey(close, open && dismissOnEscape);

  // A container-attached drawer is a panel, not a dialog — trapping focus in it
  // would strand keyboard users inside a Card. Only the viewport form is modal.
  useFocusTrap(panelRef, open && isViewport);

  useEffect(() => {
    if (!open || !isViewport) return;
    const original = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = original;
    };
  }, [open, isViewport]);

  const { mounted, className: animClass, ref: animRef } = useAnimation({
    open,
    enterClass: ENTER[side],
    exitClass: EXIT[side],
  });

  const ctx = useMemo(() => ({ open, close, side }), [open, close, side]);

  if (!mounted) return null;

  const frame = (
    <div
      data-react-fancy-drawer-frame=""
      className={cn(isViewport ? "fixed inset-0 z-50" : "absolute inset-0 z-20", !backdrop && "pointer-events-none")}
    >
      {backdrop ? (
        <div
          data-react-fancy-drawer-backdrop=""
          className={cn(
            "absolute inset-0 bg-black/40 transition-opacity",
            isViewport && "backdrop-blur-sm",
            open ? "opacity-100" : "opacity-0",
          )}
          onClick={dismissOnBackdrop ? close : undefined}
          aria-hidden="true"
        />
      ) : null}

      <div
        ref={(node) => {
          panelRef.current = node;
          (animRef as React.MutableRefObject<HTMLElement | null>).current = node;
        }}
        data-react-fancy-drawer=""
        data-side={side}
        role="dialog"
        aria-modal={isViewport || undefined}
        {...rest}
        className={cn(
          "pointer-events-auto absolute flex flex-col border-zinc-200 bg-white shadow-xl dark:border-zinc-700 dark:bg-zinc-900",
          ANCHOR[side],
          EDGE[side],
          horizontal ? WIDTH[size] : HEIGHT[size],
          // Cross-axis fills the anchor; the main axis is capped so a viewport
          // drawer can never grow past the screen on a small device.
          horizontal ? "h-full" : "w-full",
          isViewport && (horizontal ? "max-w-[90vw]" : "max-h-[90vh]"),
          !isViewport && (horizontal ? "max-w-full" : "max-h-full"),
          animClass,
          className,
        )}
      >
        {children}
      </div>
    </div>
  );

  return (
    <DrawerContext.Provider value={ctx}>
      {isViewport ? <Portal>{frame}</Portal> : frame}
    </DrawerContext.Provider>
  );
}

export const Drawer = Object.assign(DrawerRoot, {
  Header: DrawerHeader,
  Body: DrawerBody,
  Footer: DrawerFooter,
  Container: DrawerContainer,
});

import type { HTMLAttributes, ReactNode } from "react";

/** Which edge the drawer is anchored to, and therefore slides in from. */
export type DrawerSide = "left" | "right" | "top" | "bottom";

/**
 * How large the drawer is along its own axis.
 *
 * `size` controls WIDTH for `left`/`right` and HEIGHT for `top`/`bottom` — the
 * cross-axis always fills its anchor. One scale, two meanings, so `size="md"`
 * reads the same whichever edge you attach to.
 */
export type DrawerSize = "sm" | "md" | "lg" | "xl" | "full";

/**
 * Where the drawer is anchored.
 *
 * - `viewport` (default) — portalled, `fixed`, covers the screen, locks body
 *   scroll and traps focus. The classic app-level drawer.
 * - `container` — `absolute` inside the nearest positioned ancestor, no portal,
 *   no scroll lock, no focus trap. Attach it to a Card, a layout region, or the
 *   shell around a prompt input and it stays inside that box.
 */
export type DrawerAttach = "viewport" | "container";

export interface DrawerContextValue {
  open: boolean;
  close: () => void;
  side: DrawerSide;
}

export interface DrawerProps extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
  children: ReactNode;
  open: boolean;
  onClose: () => void;
  /** Edge to anchor to. Default `right`. */
  side?: DrawerSide;
  /** Extent along the drawer's own axis. Default `md`. */
  size?: DrawerSize;
  /** Viewport-level or scoped to a container. Default `viewport`. */
  attach?: DrawerAttach;
  /** Render the scrim behind the panel. Default `true`. */
  backdrop?: boolean;
  /** Clicking the scrim closes. Default `true`. */
  dismissOnBackdrop?: boolean;
  /** Escape closes. Default `true`. */
  dismissOnEscape?: boolean;
  className?: string;
}

export interface DrawerHeaderProps {
  children: ReactNode;
  /** Show the close button. Default `true`. */
  closable?: boolean;
  className?: string;
}

export interface DrawerBodyProps {
  children: ReactNode;
  className?: string;
}

export interface DrawerFooterProps {
  children: ReactNode;
  className?: string;
}

export interface DrawerContainerProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode;
  className?: string;
}

import { cn } from "../../utils/cn";
import type { DrawerBodyProps } from "./Drawer.types";

export function DrawerBody({ children, className }: DrawerBodyProps) {
  return (
    <div
      data-react-fancy-drawer-body=""
      className={cn("min-h-0 flex-1 overflow-auto px-4 py-3 text-zinc-700 dark:text-zinc-300", className)}
    >
      {children}
    </div>
