} from "react";
import { cn } from "../../utils/cn";
import { usePanZoom } from "../../hooks/use-pan-zoom";
import type { ImageViewerProps, ImageViewerViewport } from "./ImageViewer.types";

const DEFAULT_VIEWPORT: ImageViewerViewport = { panX: 0, panY: 0, zoom: 1 };

const fitClasses: Record<NonNullable<ImageViewerProps["fit"]>, string> = {
  contain: "h-full w-full object-contain",
  cover: "h-full w-full object-cover",
  none: "max-w-none object-none",
};

function clamp(n: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, n));
}

/**
 * A standalone image viewer: fits the image to its container, with optional
 * Ctrl/⌘+wheel zoom, click-drag panning, and a transparency checkerboard. Works
 * anywhere on its own and is also what `<MediaViewer>` renders for images.
 *
 * The pan/zoom viewport is controllable (`viewport` + `onViewportChange`) so an
 * agent bridge can drive it; it's uncontrolled by default.
 *
 * ```tsx
 * <ImageViewer src="/logo.png" alt="logo.png" style={{ height: 320 }} />
 * ```
 */
export const ImageViewer = forwardRef<HTMLDivElement, ImageViewerProps>(
  (
    {
      src,
      alt = "",
      fit = "contain",
      zoomable = true,
      pannable = true,
      controls,
      minZoom = 0.25,
      maxZoom = 8,
      checkerboard = true,
      viewport,
      defaultViewport,
      onViewportChange,
      onLoad,
      onError,
      className,
      style,
    },
    ref,
  ) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const [status, setStatus] = useState<"loading" | "loaded" | "error">("loading");

    // Controllable viewport supporting functional updates (usePanZoom needs them).
    const isControlled = viewport !== undefined;
    const [internal, setInternal] = useState<ImageViewerViewport>(
      defaultViewport ?? DEFAULT_VIEWPORT,
    );
    const current = isControlled ? viewport! : internal;
    const currentRef = useRef(current);
    currentRef.current = current;

    const setViewport = useCallback(
      (
        next:
          | ImageViewerViewport
          | ((prev: ImageViewerViewport) => ImageViewerViewport),
      ) => {
        const resolved =
          typeof next === "function" ? next(currentRef.current) : next;
        if (!isControlled) setInternal(resolved);
        onViewportChange?.(resolved);
      },
      [isControlled, onViewportChange],
    );

    const interactive = status === "loaded";
    const { containerProps, isPanning } = usePanZoom({
      viewport: current,
      setViewport,
      minZoom,
      maxZoom,
      pannable: pannable && interactive,
      zoomable: zoomable && interactive,
      containerRef,
    });

    // Zoom about the container centre — used by the +/− buttons.
    const zoomBy = useCallback(
      (factor: number) => {
        const el = containerRef.current;
        if (!el) return;
        const rect = el.getBoundingClientRect();
        const cx = rect.width / 2;
        const cy = rect.height / 2;
        setViewport((prev) => {
          const newZoom = clamp(prev.zoom * factor, minZoom, maxZoom);
          const ratio = newZoom / prev.zoom;
          return {
            zoom: newZoom,
            panX: cx - (cx - prev.panX) * ratio,
            panY: cy - (cy - prev.panY) * ratio,
          };
        });
      },
      [setViewport, minZoom, maxZoom],
    );

    const reset = useCallback(() => setViewport(DEFAULT_VIEWPORT), [setViewport]);

    const showControls = (controls ?? zoomable) && interactive;
    const transform = `translate(${current.panX}px, ${current.panY}px) scale(${current.zoom})`;

    return (
      <div
        ref={ref}
        data-react-fancy-image-viewer=""
        className={cn(
          "relative isolate overflow-hidden rounded-md select-none",
          checkerboard
            ? "fancy-checkerboard"
            : "bg-zinc-100 dark:bg-zinc-900",
          className,
        )}
        style={style}
      >
        <div
          ref={containerRef}
          data-canvas-bg=""
          className={cn(
            "absolute inset-0 flex items-center justify-center",
            isPanning
              ? "cursor-grabbing"
              : pannable && interactive
                ? "cursor-grab"
                : "",
          )}
          style={
            {
              transform,
              transformOrigin: "0 0",
              willChange: "transform",
              touchAction: zoomable || pannable ? "none" : undefined,
            } as CSSProperties
          }
          onDoubleClick={zoomable ? reset : undefined}
          {...containerProps}
        >
          <img
            src={src}
            alt={alt}
            draggable={false}
            onLoad={() => {
              setStatus("loaded");
              onLoad?.();
            }}
            onError={() => {
              setStatus("error");
              onError?.();
            }}
            className={cn(
              "pointer-events-none block",
              status === "error" && "hidden",
              fitClasses[fit],
            )}
          />
        </div>

        {status === "error" && (
          <div
            data-react-fancy-image-viewer-error=""
            className="absolute inset-0 flex flex-col items-center justify-center gap-1 p-4 text-center text-sm text-zinc-500 dark:text-zinc-400"
          >
            <span className="font-medium">Couldn&apos;t load image</span>
            <span className="max-w-full truncate text-xs opacity-70">{alt || src}</span>
          </div>
        )}

        {showControls && (
          <div
            data-react-fancy-image-viewer-controls=""
            className="absolute bottom-2 right-2 flex items-center gap-0.5 rounded-md border border-zinc-200 bg-white/90 p-0.5 text-zinc-700 shadow-sm backdrop-blur dark:border-zinc-700 dark:bg-zinc-900/90 dark:text-zinc-200"
          >
            <button
              type="button"
              aria-label="Zoom out"
              onClick={() => zoomBy(1 / 1.25)}
              className="flex h-6 w-6 items-center justify-center rounded text-base leading-none hover:bg-zinc-100 dark:hover:bg-zinc-800"
            >
              −
            </button>
            <button
              type="button"
              aria-label="Reset zoom"
              onClick={reset}
              className="min-w-[3rem] rounded px-1 text-center text-xs tabular-nums hover:bg-zinc-100 dark:hover:bg-zinc-800"
            >
              {Math.round(current.zoom * 100)}%
            </button>
            <button
              type="button"
              aria-label="Zoom in"
              onClick={() => zoomBy(1.25)}
              className="flex h-6 w-6 items-center justify-center rounded text-base leading-none hover:bg-zinc-100 dark:hover:bg-zinc-800"
            >
              +
            </button>
          </div>
        )}
      </div>
    );
  },
);

ImageViewer.displayName = "ImageViewer";

import type { CSSProperties } from "react";

/** Pan offset (in container pixels) + zoom factor for an `<ImageViewer>`. */
export interface ImageViewerViewport {
  panX: number;
  panY: number;
  zoom: number;
}

export interface ImageViewerProps {
  /** Image source — an `http(s):`, `data:`, or `blob:` URL. */
  src: string;
  /** Alt text for the image (also used as the download filename hint). */
  alt?: string;
  /**
   * How the image sits in its container at zoom 1. `"contain"` (default) fits
   * the whole image, `"cover"` fills and crops, `"none"` shows it at natural
   * size (pan to see the rest).
   */
  fit?: "contain" | "cover" | "none";
  /** Allow Ctrl/⌘+wheel zoom and the zoom controls (default `true`). */
  zoomable?: boolean;
  /** Allow click-drag panning (default `true`). */
  pannable?: boolean;
  /** Show the floating zoom controls. Defaults to the value of `zoomable`. */
  controls?: boolean;
  /** Minimum zoom factor (default `0.25`). */
  minZoom?: number;
  /** Maximum zoom factor (default `8`). */
  maxZoom?: number;
  /**
   * Paint a checkerboard behind the image so transparency reads clearly
   * (default `true`). Set `false` for a flat themed surface.
   */
  checkerboard?: boolean;
  /**
   * Controlled viewport (pan + zoom). Pair with `onViewportChange`. Omit for
   * uncontrolled internal state. Exposed so an agent can pan/zoom to point at
   * something via a bridge.
   */
  viewport?: ImageViewerViewport;
  /** Initial viewport when uncontrolled. */
  defaultViewport?: ImageViewerViewport;
  /** Called whenever the viewport (pan/zoom) changes. */
  onViewportChange?: (viewport: ImageViewerViewport) => void;
  /** Fired when the image finishes loading. */
  onLoad?: () => void;
  /** Fired when the image fails to load. */
  onError?: () => void;
  /** Additional CSS classes for the viewport container. */
  className?: string;
  /** Inline styles for the viewport container (e.g. a fixed height). */
  style?: CSSProperties;
}

import {
  type CSSProperties,
  type ReactNode,
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";

/**
 * InputTag — attach a `/`-style or `@`-style autocomplete picker to *any*
 * text surface (a `<textarea>`, an `<input>`, a `contenteditable`, a code
 * editor, a sheet cell editor, a whiteboard sticky note…) via an adapter
 * that abstracts the surface's read/write/caret API.
 *
 * The component is "headless" in the sense that it has no input of its
 * own — it floats a small picker menu near the surface and writes back
 * through the adapter when the user picks an item.
 *
 *   <textarea ref={ref} value={text} onChange={...} />
 *   <InputTag
 *     adapter={textareaAdapter(ref)}
 *     triggers={{
 *       "/": { items: commands, insert: (c) => `${c.name} ` },
 *       "@": { items: mentions, insert: (m) => `@${m.name} ` },
 *     }}
 *   />
 *
 * For non-DOM surfaces, write a small adapter that conforms to
 * {@link InputTagAdapter}. Adapters typically run 20–40 lines.
 */

/** What the surface tells the picker on every text/caret change. */
export type InputTagAdapterState = {
  text: string;
  caretIndex: number;
};

/**
 * The contract every input surface implements. The picker subscribes to
 * state changes, anchors itself using `getAnchorRect`, intercepts
 * navigation keys via `onKey`, and writes the selected item back through
 * `replaceRange`.
 */
export type InputTagAdapter = {
  /** Push current state whenever text or caret changes. Returns an unsubscribe. */
  subscribe: (fn: (state: InputTagAdapterState) => void) => () => void;
  /** Replace text in `[start, end)` with `replacement`. The adapter is
   *  responsible for moving the caret to the end of the inserted text. */
  replaceRange: (start: number, end: number, replacement: string) => void;
  /** Screen-space rect to anchor the picker against. Usually the surface's
   *  bounding rect; for editors that can compute caret-precise coordinates,
   *  return a small rect there instead. */
  getAnchorRect: () => DOMRect | null;
  /** Subscribe to keydown events on the surface. The handler may return
   *  `true` to consume the event (the adapter then calls
   *  `preventDefault` / `stopPropagation`). Returns an unsubscribe. */
  onKey: (handler: (e: KeyboardEvent) => boolean) => () => void;
};

/**
 * Per-trigger configuration. `T` is the item shape — typically a
 * `{ id, name, ... }` object, but any shape works as long as `keyOf` /
 * `insert` know how to handle it.
 */
export type InputTagTrigger<T> = {
  /** The pool the picker filters against. */
  items: T[];
  /** Text inserted in place of `<triggerChar><query>`. */
  insert: (item: T, query: string) => string;
  /** Custom filter. Default: case-insensitive prefix match against
   *  `String(keyOf(item))`. Pass `() => true` to disable filtering and
   *  rely on `items` being pre-filtered (e.g. from an async source). */
  filter?: (item: T, query: string) => boolean;
  /** How to render each row. Default renders the result of `keyOf(item)`. */
  render?: (item: T, active: boolean) => ReactNode;
  /** How to derive a stable key + default label for each item. Default
   *  reads `item.name` then `item.id` then `String(item)`. */
  keyOf?: (item: T) => string;
  /** Optional header label shown above the list. */
  label?: string;
};

export type InputTagTriggers = Record<string, InputTagTrigger<any>>;

export interface InputTagProps {
  adapter: InputTagAdapter;
  triggers: InputTagTriggers;
  /** Max rows shown. Default 8. */
  maxItems?: number;
  /** Where the picker anchors relative to the surface. Default `"bottom-left"`. */
  placement?: "bottom-left" | "bottom-right" | "top-left" | "top-right";
  /** Custom class for the popover container. */
  className?: string;
  /** Inline style for the popover container. */
  style?: CSSProperties;
  /** Fires whenever an item is picked. */
  onPick?: (info: { triggerChar: string; query: string; item: unknown }) => void;
};

type ActiveTrigger = {
  char: string;
  start: number;
  end: number;
  query: string;
};

function defaultKeyOf(item: unknown): string {
  if (item && typeof item === "object") {
    const r = item as Record<string, unknown>;
    if (typeof r.name === "string") return r.name;
    if (typeof r.id === "string") return r.id;
  }
  return String(item);
}

function defaultFilter(item: unknown, query: string): boolean {
  if (!query) return true;
  return defaultKeyOf(item).toLowerCase().includes(query.toLowerCase());
}

/**
 * Walk back from `caret` to detect an active trigger. A trigger is active
 * when one of the configured characters appears between `caret` and the
 * nearest preceding whitespace (or start-of-text), with no other
 * non-trigger-non-whitespace breaks. The "query" is everything after
 * the trigger up to the caret.
 */
function detectTrigger(
  text: string,
  caret: number,
  triggerChars: Set<string>,
): ActiveTrigger | null {
  for (let i = caret - 1; i >= 0; i--) {
    const ch = text[i];
    if (ch === undefined) break;
    if (triggerChars.has(ch)) {
      // Must be at a word boundary: start of text OR preceded by whitespace.
      if (i === 0 || /\s/.test(text[i - 1])) {
        return {
          char: ch,
          start: i,
          end: caret,
          query: text.slice(i + 1, caret),
        };
      }
      return null;
    }
    if (/\s/.test(ch)) return null;
  }
  return null;
}

export function InputTag({
  adapter,
  triggers,
  maxItems = 8,
  placement = "bottom-left",
  className,
  style,
  onPick,
}: InputTagProps) {
  const triggerChars = useMemo(() => new Set(Object.keys(triggers)), [triggers]);
  const [active, setActive] = useState<ActiveTrigger | null>(null);
  const [cursor, setCursor] = useState(0);
  const [anchorRect, setAnchorRect] = useState<DOMRect | null>(null);

  // Latest state in refs so key handlers see fresh data without re-registering.
  const stateRef = useRef<InputTagAdapterState>({ text: "", caretIndex: 0 });
  const activeRef = useRef<ActiveTrigger | null>(null);
  const cursorRef = useRef(0);
  activeRef.current = active;
  cursorRef.current = cursor;

  // Filtered items for the active trigger.
  const items: unknown[] = useMemo(() => {
    if (!active) return [];
    const cfg = triggers[active.char];
    if (!cfg) return [];
    const filter = cfg.filter ?? defaultFilter;
    const out: unknown[] = [];
    for (const item of cfg.items) {
      if (filter(item, active.query)) out.push(item);
      if (out.length >= maxItems) break;
    }
    return out;
  }, [active, triggers, maxItems]);

  // Subscribe to text/caret changes.
  useEffect(() => {
    return adapter.subscribe((s) => {
      stateRef.current = s;
      const next = detectTrigger(s.text, s.caretIndex, triggerChars);
      setActive((prev) => {
        // Reset cursor when the trigger char or position changes.
        if (!prev || !next || prev.char !== next.char || prev.start !== next.start) {
          setCursor(0);
        }
        return next;
      });
      if (next) setAnchorRect(adapter.getAnchorRect());
    });
  }, [adapter, triggerChars]);

  // Refresh anchor rect on scroll/resize while picker is open.
  useLayoutEffect(() => {
    if (!active) return;
    const update = () => setAnchorRect(adapter.getAnchorRect());
    update();
    window.addEventListener("scroll", update, true);
    window.addEventListener("resize", update);
    return () => {
      window.removeEventListener("scroll", update, true);
      window.removeEventListener("resize", update);
    };
  }, [active, adapter]);

  // Clamp cursor when the visible items shrink.
  useEffect(() => {
    if (cursor >= items.length) setCursor(Math.max(0, items.length - 1));
  }, [items.length, cursor]);

  const pickItem = useCallback(
    (item: unknown) => {
      const cur = activeRef.current;
      if (!cur) return;
      const cfg = triggers[cur.char];
      if (!cfg) return;
      const replacement = cfg.insert(item, cur.query);
      adapter.replaceRange(cur.start, cur.end, replacement);
      onPick?.({ triggerChar: cur.char, query: cur.query, item });
      setActive(null);
    },
    [adapter, triggers, onPick],
  );

  // Key handling.
  useEffect(() => {
    return adapter.onKey((e) => {
      const cur = activeRef.current;
      if (!cur) return false;
      const visible = items;
      switch (e.key) {
        case "ArrowDown":
          if (visible.length === 0) return false;
          setCursor((c) => (c + 1) % visible.length);
          return true;
        case "ArrowUp":
          if (visible.length === 0) return false;
          setCursor((c) => (c - 1 + visible.length) % visible.length);
          return true;
        case "Enter":
        case "Tab": {
          if (visible.length === 0) return false;
          const idx = Math.min(cursorRef.current, visible.length - 1);
          pickItem(visible[idx]);
          return true;
        }
        case "Escape":
          setActive(null);
          return true;
        default:
          return false;
      }
    });
  }, [adapter, items, pickItem]);

  if (!active || !anchorRect || items.length === 0) return null;

  const cfg = triggers[active.char];
  if (!cfg) return null;

  const popStyle = computePopoverStyle(anchorRect, placement);

  return (
    <div
      role="listbox"
      aria-label={cfg.label ?? `Pick a ${active.char === "/" ? "command" : "mention"}`}
      className={[
        "fixed z-50 w-72 overflow-hidden rounded-md border border-zinc-200 bg-white shadow-lg dark:border-zinc-700 dark:bg-zinc-900",
        className ?? "",
      ]
        .filter(Boolean)
        .join(" ")}
      style={{ ...popStyle, ...style }}
    >
      {(cfg.label || active.query) && (
        <div className="flex items-center justify-between border-b border-zinc-100 bg-zinc-50 px-2 py-1 text-[10px] font-semibold uppercase tracking-wider text-zinc-500 dark:border-zinc-800 dark:bg-zinc-950">
          <span>{cfg.label ?? labelForChar(active.char)}</span>
          {active.query && (
            <span className="font-mono text-[10px] normal-case tracking-normal text-zinc-400">
              {active.char}
              {active.query}
            </span>
          )}
        </div>
      )}
      <ul className="max-h-60 overflow-y-auto">
        {items.map((item, i) => {
          const renderer = cfg.render ?? ((it: unknown) => <span>{defaultKeyOf(it)}</span>);
          const active2 = i === cursor;
          const key = (cfg.keyOf ?? defaultKeyOf)(item);
          return (
            <li
              key={key}
              role="option"
              aria-selected={active2}
              onMouseDown={(e) => {
                e.preventDefault();
                pickItem(item);
              }}
              onMouseEnter={() => setCursor(i)}
              className={[
                "cursor-pointer px-2 py-1.5 text-[12px]",
                active2
                  ? "bg-violet-100 dark:bg-violet-900/30"
                  : "hover:bg-zinc-50 dark:hover:bg-zinc-800",
              ].join(" ")}
            >
              {renderer(item, active2)}
            </li>
          );
        })}
      </ul>
    </div>
  );
}

function labelForChar(ch: string): string {
  if (ch === "/") return "Commands";
  if (ch === "@") return "Mentions";
  if (ch === "#") return "Tags";
  if (ch === ":") return "Emoji";
  return `Trigger ${ch}`;
}

function computePopoverStyle(
  anchor: DOMRect,
  placement: NonNullable<InputTagProps["placement"]>,
): CSSProperties {
  const offset = 4;
  switch (placement) {
    case "bottom-right":
      return { top: anchor.bottom + offset, right: window.innerWidth - anchor.right };
    case "top-left":
      return { bottom: window.innerHeight - anchor.top + offset, left: anchor.left };
    case "top-right":
      return { bottom: window.innerHeight - anchor.top + offset, right: window.innerWidth - anchor.right };
    case "bottom-left":
    default:
      return { top: anchor.bottom + offset, left: anchor.left };
  }
}

import type { RefObject } from "react";
import type { InputTagAdapter } from "./InputTag";

/**
 * Built-in DOM adapters. Each one wraps a familiar input element and
 * exposes the {@link InputTagAdapter} contract so `<InputTag>` can
 * attach to it. For non-DOM surfaces (code editor, sheet cell editor,
 * whiteboard sticky note), write your own — the contract is small.
 */

/**
 * Get React's monkey-patched-aside native value setter on a DOM
 * element. Required when programmatically updating `value` on a
 * controlled input: React's intercepted setter would otherwise swallow
 * the change and the consumer's `onChange` would never fire.
 */
function nativeValueSetter(el: HTMLInputElement | HTMLTextAreaElement): ((v: string) => void) | null {
  const proto = el instanceof HTMLTextAreaElement ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
  const desc = Object.getOwnPropertyDescriptor(proto, "value");
  if (!desc?.set) return null;
  return desc.set.bind(el);
}

function replaceInValueElement(
  el: HTMLInputElement | HTMLTextAreaElement,
  start: number,
  end: number,
  replacement: string,
): void {
  const current = el.value;
  const next = current.slice(0, start) + replacement + current.slice(end);
  const setter = nativeValueSetter(el);
  if (setter) {
    setter(next);
  } else {
    el.value = next;
  }
  // Dispatch a native `input` event so any controlled-component
  // onChange handler upstream gets the new value.
  el.dispatchEvent(new Event("input", { bubbles: true }));
  // Place caret at the end of the inserted text.
  const caret = start + replacement.length;
  el.setSelectionRange(caret, caret);
  el.focus();
}

function valueElementAdapter(
  ref: RefObject<HTMLTextAreaElement | HTMLInputElement | null>,
): InputTagAdapter {
  return {
    subscribe(fn) {
      const handler = () => {
        const el = ref.current;
        if (!el) return;
        fn({
          text: el.value,
          caretIndex: el.selectionStart ?? el.value.length,
        });
      };
      const el = ref.current;
      if (el) {
        el.addEventListener("input", handler);
        el.addEventListener("click", handler);
        el.addEventListener("keyup", handler);
        el.addEventListener("focus", handler);
      }
      return () => {
        const el2 = ref.current;
        if (el2) {
          el2.removeEventListener("input", handler);
          el2.removeEventListener("click", handler);
          el2.removeEventListener("keyup", handler);
          el2.removeEventListener("focus", handler);
        }
      };
    },
    replaceRange(start, end, replacement) {
      const el = ref.current;
      if (!el) return;
      replaceInValueElement(el, start, end, replacement);
    },
    getAnchorRect() {
      const el = ref.current;
      return el ? el.getBoundingClientRect() : null;
    },
    onKey(handler) {
      const fn = (e: KeyboardEvent) => {
        if (handler(e)) {
          e.preventDefault();
          e.stopPropagation();
        }
      };
      const el = ref.current;
      if (el) el.addEventListener("keydown", fn as EventListener);
      return () => {
        const el2 = ref.current;
        if (el2) el2.removeEventListener("keydown", fn as EventListener);
      };
    },
  };
}

/**
 * Adapter for a DOM `<textarea>`. Works whether the consumer manages
 * `value` via React state (controlled) or lets the DOM hold it
 * (uncontrolled) — `replaceRange` uses React's native value setter and
 * dispatches a native `input` event so the upstream onChange fires.
 */
export function textareaAdapter(
  ref: RefObject<HTMLTextAreaElement | null>,
): InputTagAdapter {
  return valueElementAdapter(ref);
}

/** Adapter for a DOM `<input type="text|search|...">`. */
export function inputAdapter(
  ref: RefObject<HTMLInputElement | null>,
): InputTagAdapter {
  return valueElementAdapter(ref);
}

/**
 * Adapter for any `contenteditable` element. Operates on the element's
 * `textContent`; rich-text editors with their own internal model should
 * write a custom adapter that talks to that model instead.
 */
export function contentEditableAdapter(
  ref: RefObject<HTMLElement | null>,
): InputTagAdapter {
  function caretIndex(el: HTMLElement): number {
    const sel = window.getSelection();
    if (!sel || sel.rangeCount === 0) return 0;
    const range = sel.getRangeAt(0).cloneRange();
    range.selectNodeContents(el);
    range.setEnd(sel.focusNode!, sel.focusOffset);
    return range.toString().length;
  }
  function setCaret(el: HTMLElement, index: number): void {
    const sel = window.getSelection();
    if (!sel) return;
    const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
    let remaining = index;
    let node: Node | null = walker.nextNode();
    while (node) {
      const len = (node.textContent ?? "").length;
      if (remaining <= len) {
        const range = document.createRange();
        range.setStart(node, remaining);
        range.collapse(true);
        sel.removeAllRanges();
        sel.addRange(range);
        return;
      }
      remaining -= len;
      node = walker.nextNode();
    }
    // Past end: place at end.
    const range = document.createRange();
    range.selectNodeContents(el);
    range.collapse(false);
    sel.removeAllRanges();
    sel.addRange(range);
  }
  return {
    subscribe(fn) {
      const handler = () => {
        const el = ref.current;
        if (!el) return;
        fn({ text: el.textContent ?? "", caretIndex: caretIndex(el) });
      };
      const el = ref.current;
      if (el) {
        el.addEventListener("input", handler);
        el.addEventListener("click", handler);
        el.addEventListener("keyup", handler);
        el.addEventListener("focus", handler);
      }
      return () => {
        const el2 = ref.current;
        if (el2) {
          el2.removeEventListener("input", handler);
          el2.removeEventListener("click", handler);
          el2.removeEventListener("keyup", handler);
          el2.removeEventListener("focus", handler);
        }
      };
    },
    replaceRange(start, end, replacement) {
      const el = ref.current;
      if (!el) return;
      const current = el.textContent ?? "";
      const next = current.slice(0, start) + replacement + current.slice(end);
      el.textContent = next;
      setCaret(el, start + replacement.length);
      el.dispatchEvent(new Event("input", { bubbles: true }));
      el.focus();
    },
    getAnchorRect() {
      const el = ref.current;
      return el ? el.getBoundingClientRect() : null;
    },
    onKey(handler) {
      const fn = (e: KeyboardEvent) => {
        if (handler(e)) {
          e.preventDefault();
          e.stopPropagation();
        }
      };
      const el = ref.current;
      if (el) el.addEventListener("keydown", fn as EventListener);
      return () => {
        const el2 = ref.current;
        if (el2) el2.removeEventListener("keydown", fn as EventListener);
      };
    },
  };
}

/**
 * Adapter for hosts that fully control the text state themselves. Use
 * this when you can't (or don't want to) let the DOM be the source of
 * truth — for code editors with internal state, sheet cell editors, or
 * any host that already has `value` + `onChange` and wants to reach the
 * picker programmatically.
 *
 * The host calls `notify({ text, caretIndex })` after every text or
 * caret change. `<InputTag>` calls `onReplaceRange` to write back.
 */
export type ControlledAdapterHandle = InputTagAdapter & {
  /** Push the latest text + caret to the picker. */
  notify: (state: { text: string; caretIndex: number }) => void;
};

export function controlledAdapter(opts: {
  /** Element used as anchor + key target. Usually the visible input. */
  anchorRef: RefObject<HTMLElement | null>;
  /** Called when the picker writes back an insertion. */
  onReplaceRange: (start: number, end: number, replacement: string) => void;
}): ControlledAdapterHandle {
  let listener: ((s: { text: string; caretIndex: number }) => void) | null = null;
  let keyHandler: ((e: KeyboardEvent) => boolean) | null = null;

  const installKey = () => {
    const el = opts.anchorRef.current;
    if (!el || !keyHandler) return () => {};
    const fn = (e: KeyboardEvent) => {
      if (keyHandler && keyHandler(e)) {
        e.preventDefault();
        e.stopPropagation();
      }
    };
    el.addEventListener("keydown", fn);
    return () => el.removeEventListener("keydown", fn);
  };

  return {
    notify(state) {
      listener?.(state);
    },
    subscribe(fn) {
      listener = fn;
      return () => {
        if (listener === fn) listener = null;
      };
    },
    replaceRange(start, end, replacement) {
      opts.onReplaceRange(start, end, replacement);
    },
    getAnchorRect() {
      const el = opts.anchorRef.current;
      return el ? el.getBoundingClientRect() : null;
    },
    onKey(handler) {
      keyHandler = handler;
      const uninstall = installKey();
      return () => {
        if (keyHandler === handler) keyHandler = null;
        uninstall();
      };
    },
  };
}

