import { Button, Input, Textarea } from "@particle-academy/react-fancy";
import type { LlmsLink, LlmsSection, LlmsTxtModel } from "../model.js";
import { validateLlmsTxt } from "../validate.js";
import { IssueList, Section } from "./internal.js";

export interface LlmsTxtEditorProps {
  value: LlmsTxtModel;
  onChange: (next: LlmsTxtModel) => void;
  hideIssues?: boolean;
  className?: string;
}

/** Controlled llms.txt editor: title/summary/details + repeatable sections. */
export function LlmsTxtEditor({
  value,
  onChange,
  hideIssues,
  className,
}: LlmsTxtEditorProps) {
  const issues = validateLlmsTxt(value);
  const patch = (next: Partial<LlmsTxtModel>) => onChange({ ...value, ...next });

  const updateSection = (index: number, next: Partial<LlmsSection>) => {
    const sections = value.sections.map((s, i) =>
      i === index ? { ...s, ...next } : s,
    );
    patch({ sections });
  };

  const addSection = () =>
    patch({ sections: [...value.sections, { name: "", links: [] }] });

  const removeSection = (index: number) =>
    patch({ sections: value.sections.filter((_, i) => i !== index) });

  const updateLink = (
    si: number,
    li: number,
    next: Partial<LlmsLink>,
  ) => {
    const links = value.sections[si].links.map((l, i) =>
      i === li ? { ...l, ...next } : l,
    );
    updateSection(si, { links });
  };

  const addLink = (si: number) =>
    updateSection(si, {
      links: [...value.sections[si].links, { title: "", url: "" }],
    });

  const removeLink = (si: number, li: number) =>
    updateSection(si, {
      links: value.sections[si].links.filter((_, i) => i !== li),
    });

  return (
    <div className={className} data-x-editor="llmsTxt">
      <Section title="Header" handle="llms-header">
        <Input
          label="Title"
          value={value.title}
          onValueChange={(title) => patch({ title })}
          placeholder="Example Corp"
          data-x-input="llms-title"
        />
        <Textarea
          label="Summary"
          value={value.summary ?? ""}
          onValueChange={(v) => patch({ summary: v || undefined })}
          placeholder="One-line blockquote summary."
          data-x-input="llms-summary"
        />
        <Textarea
          label="Details"
          value={value.details ?? ""}
          onValueChange={(v) => patch({ details: v || undefined })}
          placeholder="Free-form Markdown paragraph(s)."
          data-x-input="llms-details"
        />
      </Section>

      <Section
        title="Sections"
        handle="llms-sections"
        action={
          <Button
            type="button"
            variant="ghost"
            onClick={addSection}
            data-x-add="llms-section"
          >
            Add section
          </Button>
        }
      >
        {value.sections.map((section, si) => (
          <div
            key={si}
            data-x-section-row={si}
            style={{
              border: "1px solid var(--rf-border, #e5e7eb)",
              borderRadius: "0.5rem",
              padding: "0.75rem",
              display: "flex",
              flexDirection: "column",
              gap: "0.5rem",
            }}
          >
            <div style={{ display: "flex", gap: "0.5rem", alignItems: "end" }}>
              <div style={{ flex: 1 }}>
                <Input
                  label="Section name"
                  value={section.name}
                  onValueChange={(name) => updateSection(si, { name })}
                  placeholder="Docs"
                  data-x-input={`llms-section-name:${si}`}
                />
              </div>
              <Button
                type="button"
                variant="ghost"
                color="red"
                onClick={() => removeSection(si)}
                data-x-remove={`llms-section:${si}`}
              >
                Remove
              </Button>
            </div>

            {section.links.map((link, li) => (
              <div
                key={li}
                data-x-link-row={`${si}:${li}`}
                style={{
                  display: "flex",
                  gap: "0.4rem",
                  alignItems: "end",
                  flexWrap: "wrap",
                }}
              >
                <div style={{ flex: "1 1 8rem" }}>
                  <Input
                    label={li === 0 ? "Title" : undefined}
                    value={link.title}
                    onValueChange={(title) => updateLink(si, li, { title })}
                    placeholder="Getting started"
                    data-x-input={`llms-link-title:${si}:${li}`}
                  />
                </div>
                <div style={{ flex: "1 1 10rem" }}>
                  <Input
                    label={li === 0 ? "URL" : undefined}
                    value={link.url}
                    onValueChange={(url) => updateLink(si, li, { url })}
                    placeholder="https://example.com/docs"
                    data-x-input={`llms-link-url:${si}:${li}`}
                  />
                </div>
                <div style={{ flex: "1 1 8rem" }}>
                  <Input
                    label={li === 0 ? "Notes" : undefined}
                    value={link.notes ?? ""}
                    onValueChange={(v) =>
                      updateLink(si, li, { notes: v || undefined })
                    }
                    placeholder="optional"
                    data-x-input={`llms-link-notes:${si}:${li}`}
                  />
                </div>
                <Button
                  type="button"
                  variant="ghost"
                  color="red"
                  onClick={() => removeLink(si, li)}
                  data-x-remove={`llms-link:${si}:${li}`}
                >
                  ×
                </Button>
              </div>
            ))}
            <Button
              type="button"
              variant="ghost"
              onClick={() => addLink(si)}
              data-x-add={`llms-link:${si}`}
            >
              Add link
            </Button>
          </div>
        ))}
      </Section>

      {hideIssues ? null : <IssueList issues={issues} testid="llmsTxt" />}
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";
import { Button } from "../Button";
import { Badge } from "../Badge";
import { Textarea } from "../inputs/Textarea/Textarea";

/**
 * MagicWand — selection-anchored floating toolbar for text inputs.
 *
 * When the user highlights text inside the wrapped <Textarea>, a small
 * pill of AI quick-actions floats above the selection. Clicking an
 * action invokes the host callback with the selected substring + range;
 * the host returns a replacement string and MagicWand swaps it in-place.
 *
 *   <MagicWand
 *     value={body}
 *     onValueChange={setBody}
 *     actions={[
 *       { id: "rephrase", label: "Rephrase", hint: "same meaning, different words",
 *         run: async (s) => await ai.rephrase(s) },
 *       …
 *     ]}
 *   />
 *
 * Two appearances: `"floating"` (default — full labels) and `"pill"`
 * (icon-only, compact). Auto-hides on click-away or scroll by default.
 */
export type MagicWandSelection = { start: number; end: number; text: string };

export type MagicWandAction = {
  /** Stable id, also shown as the busy-state key. */
  id: string;
  /** Display label (first character used in `pill` mode). */
  label: string;
  /** Tooltip body. */
  hint?: string;
  /** Optional kind chip rendered next to the label. */
  tag?: string;
  /** Returns the replacement text for the selection. */
  run: (selection: string, range: MagicWandSelection) => Promise<string> | string;
};

export type MagicWandAppearance = "pill" | "floating";

export interface MagicWandProps {
  /** Controlled textarea value. */
  value: string;
  /** Called on every edit. */
  onValueChange: (v: string) => void;
  /** Action list. */
  actions: MagicWandAction[];
  /** Visual treatment. Defaults to "floating". */
  appearance?: MagicWandAppearance;
  /** Auto-hide the wand on click-away or scroll. Defaults to true. */
  autoHide?: boolean;
  /** Textarea rows. */
  rows?: number;
  /** Placeholder. */
  placeholder?: string;
  /** Called after an action runs successfully. */
  onAction?: (action: MagicWandAction, selection: MagicWandSelection, replacement: string) => void;
}

export function MagicWand({
  value,
  onValueChange,
  actions,
  appearance = "floating",
  autoHide = true,
  rows = 6,
  placeholder,
  onAction,
}: MagicWandProps) {
  const taRef = useRef<HTMLTextAreaElement>(null);
  const wandRef = useRef<HTMLDivElement>(null);
  const [sel, setSel] = useState<MagicWandSelection | null>(null);
  const [pos, setPos] = useState<{ x: number; y: number } | null>(null);
  const [busy, setBusy] = useState<string | null>(null);

  const measureSelection = useCallback(() => {
    const ta = taRef.current;
    if (!ta) return;
    const start = ta.selectionStart ?? 0;
    const end = ta.selectionEnd ?? 0;
    if (start === end) {
      setSel(null);
      setPos(null);
      return;
    }
    const text = ta.value.slice(start, end);
    setSel({ start, end, text });
    const rect = caretRect(ta, start, end);
    if (rect) setPos({ x: rect.x, y: rect.y });
  }, []);

  useEffect(() => {
    if (!autoHide) return;
    const onScroll = () => {
      setSel(null);
      setPos(null);
    };
    window.addEventListener("scroll", onScroll, true);
    return () => window.removeEventListener("scroll", onScroll, true);
  }, [autoHide]);

  useEffect(() => {
    if (!autoHide) return;
    const onDocMouseDown = (e: MouseEvent) => {
      if (wandRef.current?.contains(e.target as Node)) return;
      if (taRef.current?.contains(e.target as Node)) return;
      setSel(null);
      setPos(null);
    };
    document.addEventListener("mousedown", onDocMouseDown);
    return () => document.removeEventListener("mousedown", onDocMouseDown);
  }, [autoHide]);

  const handleAction = async (action: MagicWandAction) => {
    if (!sel) return;
    setBusy(action.id);
    try {
      const replacement = await action.run(sel.text, sel);
      const next = value.slice(0, sel.start) + replacement + value.slice(sel.end);
      onValueChange(next);
      onAction?.(action, sel, replacement);
    } finally {
      setBusy(null);
      setSel(null);
      setPos(null);
    }
  };

  return (
    <div className="relative">
      <Textarea
        ref={taRef as unknown as React.Ref<HTMLTextAreaElement>}
        value={value}
        onValueChange={onValueChange}
        onSelect={measureSelection}
        onKeyUp={measureSelection}
        onMouseUp={measureSelection}
        rows={rows}
        placeholder={placeholder}
      />
      {sel && pos && (
        <Wand
          ref={wandRef}
          pos={pos}
          actions={actions}
          appearance={appearance}
          busy={busy}
          onAction={handleAction}
          selectionLength={sel.text.length}
        />
      )}
    </div>
  );
}

function Wand({
  ref,
  pos,
  actions,
  appearance,
  busy,
  onAction,
  selectionLength,
}: {
  ref: React.RefObject<HTMLDivElement | null>;
  pos: { x: number; y: number };
  actions: MagicWandAction[];
  appearance: MagicWandAppearance;
  busy: string | null;
  onAction: (a: MagicWandAction) => void;
  selectionLength: number;
}) {
  return (
    <div
      ref={ref}
      className="absolute z-20 -translate-x-1/2 -translate-y-full"
      style={{ left: pos.x, top: pos.y - 6 }}
    >
      <div className="flex items-center gap-1 rounded-full border border-violet-300 bg-white px-1.5 py-1 shadow-lg ring-1 ring-violet-200 dark:border-violet-700 dark:bg-zinc-900 dark:ring-violet-900">
        <span className="ml-1 mr-0.5 inline-flex items-center gap-1 text-[10px] font-medium text-violet-700 dark:text-violet-300">
          <span aria-hidden>✦</span>
          {appearance === "floating" && (
            <Badge color="violet">{selectionLength} chars</Badge>
          )}
        </span>
        {actions.map((a) => (
          <Button
            key={a.id}
            size="sm"
            variant="ghost"
            onClick={() => onAction(a)}
            disabled={busy !== null}
            title={a.hint}
          >
            {busy === a.id ? "…" : appearance === "pill" ? a.label[0] : a.label}
            {appearance === "floating" && a.tag && (
              <span className="ml-1 rounded-full bg-zinc-100 px-1 text-[9px] font-medium text-zinc-500 dark:bg-zinc-800">
                {a.tag}
              </span>
            )}
          </Button>
        ))}
      </div>
      <div className="absolute left-1/2 top-full -translate-x-1/2 -translate-y-px">
        <div className="h-2 w-2 rotate-45 border-b border-r border-violet-300 bg-white dark:border-violet-700 dark:bg-zinc-900" />
      </div>
    </div>
  );
}

/**
 * Caret/selection geometry: mirror the textarea into a hidden div and
 * measure the selected substring's bounding rect. Not perfect for
 * resized textareas, but works for typical chat composers.
 */
function caretRect(
  ta: HTMLTextAreaElement,
  start: number,
  end: number,
): { x: number; y: number } | null {
  const div = document.createElement("div");
  const style = getComputedStyle(ta);
  const props = [
    "boxSizing",
    "width",
    "height",
    "overflowX",
    "overflowY",
    "borderTopWidth",
    "borderRightWidth",
    "borderBottomWidth",
    "borderLeftWidth",
    "paddingTop",
    "paddingRight",
    "paddingBottom",
    "paddingLeft",
    "fontStyle",
    "fontVariant",
    "fontWeight",
    "fontStretch",
    "fontSize",
    "fontSizeAdjust",
    "lineHeight",
    "fontFamily",
    "textAlign",
    "textTransform",
    "textIndent",
    "letterSpacing",
    "wordSpacing",
    "tabSize",
  ] as const;
  for (const p of props) (div.style as any)[p] = (style as any)[p];
  div.style.position = "absolute";
  div.style.top = "-9999px";
  div.style.left = "-9999px";
  div.style.whiteSpace = "pre-wrap";
  div.style.wordWrap = "break-word";

  const value = ta.value;
  div.textContent = value.substring(0, start);
  const startSpan = document.createElement("span");
  startSpan.textContent = value.substring(start, end) || ".";
  div.appendChild(startSpan);

  document.body.appendChild(div);
  const taRect = ta.getBoundingClientRect();
  const parentRect =
    (ta.offsetParent as HTMLElement | null)?.getBoundingClientRect() ?? taRect;
  const spanRect = startSpan.getBoundingClientRect();
  const divRect = div.getBoundingClientRect();
  const offsetX = spanRect.left - divRect.left;
  const offsetY = spanRect.top - divRect.top;
  document.body.removeChild(div);

  const x = taRect.left - parentRect.left + offsetX + spanRect.width / 2;
  const y = taRect.top - parentRect.top + offsetY - ta.scrollTop;
  return { x, y };
}

export { MagicWand } from "./MagicWand";
export type {
  MagicWandProps,
  MagicWandAction,
  MagicWandSelection,
  MagicWandAppearance,
} from "./MagicWand";

import { useEffect, useRef, useState, type CSSProperties } from "react";
import type { LatLng, MapHandle, MapMarker, MapProvider, MapView } from "./types";

export type MapProps = {
  /** The map engine to render with — `leafletProvider()` / `googleProvider({ apiKey })`. */
  provider: MapProvider;
  /** Controlled camera. */
  view: MapView;
  /** Fires when the user pans/zooms (or a provider animation settles). */
  onViewChange?: (view: MapView) => void;
  /** Controlled markers (JSON-friendly; an agent can emit these directly). */
  markers?: MapMarker[];
  /** Controlled selection. */
  selectedId?: string | null;
  onSelect?: (id: string | null, marker?: MapMarker) => void;
  /** Fires when a draggable marker is released. */
  onMarkerDragEnd?: (id: string, position: LatLng) => void;
  /** Fires when the map background (not a marker) is clicked. */
  onMapClick?: (position: LatLng) => void;
  /**
   * Live follow — keep this marker centered as its position updates. Set it to a
   * moving marker's id (a vehicle, a delivery, the agent) for live tracking.
   */
  follow?: string | null;
  /** One-shot: fit the camera to enclose these points (re-runs on array identity change). */
  fitTo?: LatLng[];
  /** Grab the imperative handle once the engine is live (e.g. for a bridge's fitBounds). */
  onReady?: (handle: MapHandle) => void;
  /** Called if the provider fails to mount (e.g. Google SDK load error). */
  onError?: (error: unknown) => void;
  className?: string;
  style?: CSSProperties;
  "aria-label"?: string;
};

const EMPTY_MARKERS: MapMarker[] = [];

/** Whether two cameras are close enough to treat as "the same" (echo guard). */
function viewsClose(a: MapView, b: MapView): boolean {
  return (
    Math.abs(a.center.lat - b.center.lat) < 1e-7 &&
    Math.abs(a.center.lng - b.center.lng) < 1e-7 &&
    Math.abs(a.zoom - b.zoom) < 1e-3
  );
}

/**
 * The engine-agnostic map surface. Fully controlled (view + markers + selection),
 * SSR-safe (renders a sized placeholder on the server; the provider mounts inside
 * an effect, so there's no `window`/engine access during render and no hydration
 * mismatch), and driveable by both a human and — via the Human+ map bridge in
 * `@particle-academy/agent-integrations` — an agent, over the same controlled state.
 */
export function Map({
  provider,
  view,
  onViewChange,
  markers = EMPTY_MARKERS,
  selectedId = null,
  onSelect,
  onMarkerDragEnd,
  onMapClick,
  follow = null,
  fitTo,
  onReady,
  onError,
  className,
  style,
  "aria-label": ariaLabel = "Map",
}: MapProps) {
  const hostRef = useRef<HTMLDivElement | null>(null);
  const handleRef = useRef<MapHandle | null>(null);
  // A bump counter that flips once the (async) provider handle is live, so the
  // prop-sync effects below re-run and apply current props to the fresh engine.
  const [ready, setReady] = useState(0);

  // Latest callbacks + the initial mount snapshot, kept in refs so the mount
  // effect stays mount-once (it only re-runs when the provider identity changes).
  const cbRef = useRef({ onViewChange, onSelect, onMarkerDragEnd, onMapClick, onReady, onError });
  cbRef.current = { onViewChange, onSelect, onMarkerDragEnd, onMapClick, onReady, onError };
  const initialRef = useRef({ view, markers, selectedId });
  // The last camera the map itself emitted — lets the view-sync effect ignore
  // the echo of a user pan (which would otherwise fight the animation).
  const lastEmitted = useRef<MapView | null>(null);

  useEffect(() => {
    const host = hostRef.current;
    if (!host) {
      return;
    }
    let disposed = false;
    let handle: MapHandle | null = null;
    const offs: Array<() => void> = [];

    Promise.resolve(
      provider.mount(host, {
        view: initialRef.current.view,
        markers: initialRef.current.markers,
        selectedId: initialRef.current.selectedId,
        interactive: true,
      }),
    )
      .then((h) => {
        if (disposed) {
          h.destroy();
          return;
        }
        handle = h;
        handleRef.current = h;
        offs.push(
          h.on("viewchange", (v) => {
            lastEmitted.current = v;
            cbRef.current.onViewChange?.(v);
          }),
          h.on("markerclick", ({ id, marker }) => cbRef.current.onSelect?.(id, marker)),
          h.on("markerdragend", ({ id, position }) => cbRef.current.onMarkerDragEnd?.(id, position)),
          h.on("click", ({ position }) => cbRef.current.onMapClick?.(position)),
        );
        cbRef.current.onReady?.(h);
        setReady((n) => n + 1);
      })
      .catch((err) => {
        if (!disposed) {
          cbRef.current.onError?.(err);
        }
      });

    return () => {
      disposed = true;
      for (const off of offs) {
        off();
      }
      handle?.destroy();
      if (handleRef.current === handle) {
        handleRef.current = null;
      }
    };
  }, [provider]);

  // Sync camera — skip the echo of the map's own emitted view.
  useEffect(() => {
    const h = handleRef.current;
    if (!h) {
      return;
    }
    if (lastEmitted.current && viewsClose(lastEmitted.current, view)) {
      return;
    }
    h.setView(view, true);
  }, [view, ready]);

  // Sync markers (provider diffs internally — cheap on live-tracking updates).
  useEffect(() => {
    handleRef.current?.setMarkers(markers);
  }, [markers, ready]);

  // Sync selection.
  useEffect(() => {
    handleRef.current?.setSelected(selectedId);
  }, [selectedId, ready]);

  // Live follow — recenter on the followed marker whenever it moves.
  useEffect(() => {
    if (!follow) {
      return;
    }
    const h = handleRef.current;
    if (!h) {
      return;
    }
    const m = markers.find((x) => x.id === follow);
    if (m) {
      h.setView({ center: m.position }, true);
    }
  }, [follow, markers, ready]);

  // One-shot fit.
  useEffect(() => {
    if (fitTo && fitTo.length) {
      handleRef.current?.fitBounds(fitTo);
    }
  }, [fitTo, ready]);

  return (
    <div
      ref={hostRef}
      className={className}
      role="region"
      aria-label={ariaLabel}
      data-fancy-map={provider.name}
      style={{ position: "relative", width: "100%", height: "100%", minHeight: 240, ...style }}
    />
  );
}

import { cn, useControllableState } from "@particle-academy/react-fancy";
import { CodeEditor } from "../CodeEditor";
import { renderMarkdown } from "../../engine/markdown-render";

export type MarkdownEditorMode = "split" | "edit" | "preview";

export interface MarkdownEditorProps {
  /** Controlled markdown value. */
  value?: string;
  /** Initial value (uncontrolled). */
  defaultValue?: string;
  /** Called with the new markdown whenever the document changes. */
  onValueChange?: (markdown: string) => void;
  /**
   * Layout: `split` (editor + live preview side by side), `edit` (editor only),
   * or `preview` (rendered only). Default `split`.
   */
  mode?: MarkdownEditorMode;
  /** Editor theme — `"light" | "dark" | "auto"` or a registered name. Default `auto`. */
  theme?: string;
  /** Prevent editing. */
  readOnly?: boolean;
  /** Show line numbers in the editor (default false — prose reads better without). */
  lineNumbers?: boolean;
  /** Wrap long lines in the editor (default true for prose). */
  wordWrap?: boolean;
  /** Placeholder shown when empty. */
  placeholder?: string;
  /** Editor height bounds (px). */
  minHeight?: number;
  maxHeight?: number;
  className?: string;
  /**
   * Swap the markdown → HTML renderer used by the preview pane (e.g. a full
   * CommonMark library). Defaults to the built-in lightweight renderer.
   */
  renderPreview?: (markdown: string) => string;
}

/**
 * A markdown-aware editor: a syntax-highlighted `CodeEditor` (the registered
 * `markdown` language) with an optional live preview pane. Controlled via
 * `value` + `onValueChange`. The preview renders with a small built-in
 * dependency-free renderer; pass `renderPreview` to use your own.
 *
 * ```tsx
 * <MarkdownEditor value={md} onValueChange={setMd} mode="split" minHeight={240} />
 * ```
 */
export function MarkdownEditor({
  value,
  defaultValue = "",
  onValueChange,
  mode = "split",
  theme = "auto",
  readOnly = false,
  lineNumbers = false,
  wordWrap = true,
  placeholder,
  minHeight,
  maxHeight,
  className,
  renderPreview = renderMarkdown,
}: MarkdownEditorProps) {
  const [content, setContent] = useControllableState(value, defaultValue, onValueChange);

  const showEditor = mode !== "preview";
  const showPreview = mode !== "edit";

  return (
    <div
      data-fancy-markdown-editor=""
      data-mode={mode}
      className={cn("fancy-md-editor", className)}
    >
      {showEditor && (
        <div className="fancy-md-editor-pane">
          <CodeEditor
            value={content}
            onChange={setContent}
            language="markdown"
            theme={theme}
            readOnly={readOnly}
            lineNumbers={lineNumbers}
            wordWrap={wordWrap}
            placeholder={placeholder}
            minHeight={minHeight}
            maxHeight={maxHeight}
          >
            <CodeEditor.Panel />
          </CodeEditor>
        </div>
      )}
      {showPreview && (
        <div
          data-fancy-markdown-preview=""
          className="fancy-md-preview"
          dangerouslySetInnerHTML={{ __html: renderPreview(content) }}
        />
      )}
