import { forwardRef } from "react";
import { cn } from "../../utils/cn";
import type { ProgressProps } from "./Progress.types";
import { progressFill, progressStroke, progressText } from "./Progress.colors";

const barHeightClasses: Record<NonNullable<ProgressProps["size"]>, string> = {
  sm: "h-1.5",
  md: "h-2.5",
  lg: "h-4",
};

const circularSizeMap: Record<NonNullable<ProgressProps["size"]>, number> = {
  sm: 32,
  md: 48,
  lg: 64,
};

const textSizeClasses: Record<NonNullable<ProgressProps["size"]>, string> = {
  sm: "text-[8px]",
  md: "text-[10px]",
  lg: "text-xs",
};

export const Progress = forwardRef<HTMLDivElement, ProgressProps>(
  (
    {
      value = 0,
      max = 100,
      variant = "bar",
      size = "md",
      color = "blue",
      indeterminate = false,
      showValue = false,
      className,
    },
    ref,
  ) => {
    const percentage = Math.min(100, Math.max(0, (value / max) * 100));

    if (variant === "circular") {
      const diameter = circularSizeMap[size];
      const strokeWidth = size === "sm" ? 3 : size === "md" ? 4 : 5;
      const radius = (diameter - strokeWidth) / 2;
      const circumference = 2 * Math.PI * radius;
      const offset = indeterminate ? circumference * 0.75 : circumference - (percentage / 100) * circumference;

      return (
        <div
          ref={ref}
          role="progressbar"
          aria-valuenow={indeterminate ? undefined : value}
          aria-valuemin={0}
          aria-valuemax={max}
          data-react-fancy-progress=""
          className={cn("relative inline-flex items-center justify-center", className)}
          style={{ width: diameter, height: diameter }}
        >
          <svg
            width={diameter}
            height={diameter}
            className={cn(indeterminate && "animate-spin")}
          >
            <circle
              cx={diameter / 2}
              cy={diameter / 2}
              r={radius}
              fill="none"
              strokeWidth={strokeWidth}
              className="stroke-zinc-200 dark:stroke-zinc-700"
            />
            <circle
              cx={diameter / 2}
              cy={diameter / 2}
              r={radius}
              fill="none"
              strokeWidth={strokeWidth}
              strokeLinecap="round"
              strokeDasharray={circumference}
              strokeDashoffset={offset}
              className={cn(progressStroke[color], "transition-[stroke-dashoffset] duration-300")}
              style={{ transform: "rotate(-90deg)", transformOrigin: "center" }}
            />
          </svg>
          {showValue && !indeterminate && (
            <span
              className={cn(
                "absolute font-medium",
                progressText[color],
                textSizeClasses[size],
              )}
            >
              {Math.round(percentage)}%
            </span>
          )}
        </div>
      );
    }

    return (
      <div
        ref={ref}
        role="progressbar"
        aria-valuenow={indeterminate ? undefined : value}
        aria-valuemin={0}
        aria-valuemax={max}
        data-react-fancy-progress=""
        className={cn("relative w-full", className)}
      >
        <div
          className={cn(
            "w-full overflow-hidden rounded-full bg-zinc-200 dark:bg-zinc-700",
            barHeightClasses[size],
          )}
        >
          <div
            className={cn(
              "h-full rounded-full transition-[width] duration-300",
              progressFill[color],
              indeterminate && "animate-pulse w-full",
            )}
            style={indeterminate ? undefined : { width: `${percentage}%` }}
          />
        </div>
        {showValue && !indeterminate && (
          <span
            className={cn(
              "mt-1 block text-right text-xs font-medium",
              progressText[color],
            )}
          >
            {Math.round(percentage)}%
          </span>
        )}
      </div>
    );
  },
);

Progress.displayName = "Progress";

import type { Color } from "../../utils/types";

export interface ProgressProps {
  value?: number;
  max?: number;
  variant?: "bar" | "circular";
  size?: "sm" | "md" | "lg";
  color?: Color;
  indeterminate?: boolean;
  showValue?: boolean;
  className?: string;
}

import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { Button } from "../Button";
import { Tooltip } from "../Tooltip";

/**
 * PromptInput — the chat composer every AI app rebuilds. Auto-growing
 * multi-line input with:
 *
 *   • slash-command picker (`/` triggers a filtered command palette,
 *     ↑/↓ navigate, Enter inserts)
 *   • mention picker (`@` triggers, filtered against `mentions`)
 *   • drop-to-attach (drag files anywhere on the surface) + chip bar
 *   • submit on ⌘/Ctrl+Enter (plain Enter inserts a newline)
 *   • live token-budget meter (green → amber → red as headroom drops)
 *
 * Wire it up:
 *
 *   <PromptInput
 *     budgetTokens={32000}
 *     commands={[{ name: "/rewrite", hint: "rewrite the selection" }]}
 *     mentions={[{ id: "ada", name: "Ada", kind: "person" }]}
 *     onSubmit={(text, attachments) => sendToAgent(text, attachments)}
 *   />
 */
export type PromptCmd = { name: string; hint: string };
export type PromptMention = {
  id: string;
  name: string;
  kind: "agent" | "file" | "person" | string;
};
export type PromptAttachment = { id: string; name: string; bytes: number };

export interface PromptInputProps {
  /** Token budget for the meter. */
  budgetTokens: number;
  /** Slash-commands. Names must start with `/`. */
  commands?: PromptCmd[];
  /** @-mentions. */
  mentions?: PromptMention[];
  /** Show the keyboard hint ("⌘ + Enter to send"). */
  showHint?: boolean;
  /** Called on ⌘/Ctrl+Enter or send button. */
  onSubmit: (text: string, attachments: PromptAttachment[]) => void;
  /** Placeholder text. */
  placeholder?: string;
  /** Rough estimator: chars-per-token. Defaults to 4. */
  charsPerToken?: number;
  /** Color → CSS chip mapping for mention kinds. */
  mentionColor?: Record<string, string>;
  /** Optional max textarea height in px. Defaults to 280. */
  maxHeight?: number;
  /**
   * Rendered INSIDE the rounded shell, ABOVE the attachments bar and
   * textarea. Use this slot for a drawer of tools/files/prompts/etc. so
   * the drawer and composer share one visual panel. See {@link ChatDrawer}.
   */
  aboveInput?: ReactNode;
}

const DEFAULT_MENTION_COLOR: Record<string, string> = {
  agent: "#a855f7",
  file: "#10b981",
  person: "#3b82f6",
};

export function PromptInput({
  budgetTokens,
  commands = [],
  mentions = [],
  showHint = true,
  onSubmit,
  placeholder = "Ask anything. Type / for commands, @ for mentions. ⌘/Ctrl+Enter to send.",
  charsPerToken = 4,
  mentionColor,
  maxHeight = 280,
  aboveInput,
}: PromptInputProps) {
  const [text, setText] = useState("");
  const [attachments, setAttachments] = useState<PromptAttachment[]>([]);
  const [picker, setPicker] = useState<null | {
    kind: "cmd" | "mention";
    start: number;
    query: string;
    cursor: number;
  }>(null);
  const taRef = useRef<HTMLTextAreaElement>(null);
  const [dragOver, setDragOver] = useState(false);

  const colors = mentionColor ?? DEFAULT_MENTION_COLOR;

  const tokens = useMemo(
    () => Math.ceil(text.length / Math.max(1, charsPerToken)),
    [text, charsPerToken],
  );
  const ratio = Math.min(1, tokens / budgetTokens);
  const meterColor = ratio < 0.6 ? "#10b981" : ratio < 0.85 ? "#f59e0b" : "#ef4444";

  const filteredCmds = useMemo(
    () =>
      picker?.kind === "cmd"
        ? commands.filter((c) =>
            c.name.slice(1).toLowerCase().startsWith(picker.query.toLowerCase()),
          )
        : [],
    [picker, commands],
  );
  const filteredMentions = useMemo(
    () =>
      picker?.kind === "mention"
        ? mentions.filter((m) =>
            m.name.toLowerCase().includes(picker.query.toLowerCase()),
          )
        : [],
    [picker, mentions],
  );
  const items: Array<PromptCmd | PromptMention> =
    picker?.kind === "cmd"
      ? filteredCmds
      : picker?.kind === "mention"
        ? filteredMentions
        : [];

  useEffect(() => {
    const ta = taRef.current;
    if (!ta) return;
    ta.style.height = "auto";
    ta.style.height = Math.min(maxHeight, ta.scrollHeight) + "px";
  }, [text, maxHeight]);

  const updateText = (next: string, caret: number) => {
    setText(next);
    let triggerIdx = -1;
    let triggerKind: "cmd" | "mention" | null = null;
    for (let i = caret - 1; i >= 0; i--) {
      const ch = next[i];
      if (ch === "@") {
        triggerKind = "mention";
        triggerIdx = i;
        break;
      }
      if (ch === "/" && (i === 0 || /\s/.test(next[i - 1] ?? ""))) {
        triggerKind = "cmd";
        triggerIdx = i;
        break;
      }
      if (/\s/.test(ch)) break;
    }
    if (triggerKind !== null && triggerIdx >= 0) {
      const query = next.slice(triggerIdx + 1, caret);
      setPicker({ kind: triggerKind, start: triggerIdx, query, cursor: 0 });
    } else {
      setPicker(null);
    }
  };

  const insertChoice = (i: number) => {
    if (!picker || items.length === 0) return;
    const choice = items[i] ?? items[0];
    const insert =
      picker.kind === "cmd"
        ? (choice as PromptCmd).name + " "
        : `@${(choice as PromptMention).id} `;
    const before = text.slice(0, picker.start);
    const after = text.slice(picker.start + 1 + picker.query.length);
    const next = before + insert + after;
    setText(next);
    setPicker(null);
    requestAnimationFrame(() => {
      const ta = taRef.current;
      if (!ta) return;
      ta.focus();
      const pos = before.length + insert.length;
      ta.setSelectionRange(pos, pos);
    });
  };

  const submit = () => {
    if (!text.trim() && attachments.length === 0) return;
    onSubmit(text, attachments);
    setText("");
    setAttachments([]);
    setPicker(null);
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (picker) {
      if (e.key === "ArrowDown") {
        e.preventDefault();
        setPicker((p) =>
          p ? { ...p, cursor: Math.min(items.length - 1, p.cursor + 1) } : p,
        );
        return;
      }
      if (e.key === "ArrowUp") {
        e.preventDefault();
        setPicker((p) => (p ? { ...p, cursor: Math.max(0, p.cursor - 1) } : p));
        return;
      }
      if (e.key === "Enter" && !e.metaKey && !e.ctrlKey && items.length > 0) {
        e.preventDefault();
        insertChoice(picker.cursor);
        return;
      }
      if (e.key === "Escape") {
        e.preventDefault();
        setPicker(null);
        return;
      }
    }
    if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) {
      e.preventDefault();
      submit();
    }
  };

  const onDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setDragOver(false);
    const files = Array.from(e.dataTransfer.files);
    setAttachments((cur) => [
      ...cur,
      ...files.map((f) => ({
        id: `${f.name}-${Date.now()}-${Math.random()}`,
        name: f.name,
        bytes: f.size,
      })),
    ]);
  };

  return (
    <div
      onDragOver={(e) => {
        e.preventDefault();
        setDragOver(true);
      }}
      onDragLeave={() => setDragOver(false)}
      onDrop={onDrop}
      className={`relative rounded-md border transition ${
        dragOver
          ? "border-violet-400 bg-violet-50/50 dark:border-violet-600 dark:bg-violet-950/30"
          : "border-zinc-200 dark:border-zinc-800"
      } bg-white dark:bg-zinc-900`}
    >
      {aboveInput && (
        <div className="border-b border-zinc-200 dark:border-zinc-800">
          {aboveInput}
        </div>
      )}
      {attachments.length > 0 && (
        <div className="flex flex-wrap gap-1.5 border-b border-zinc-200 px-3 py-2 dark:border-zinc-800">
          {attachments.map((a) => (
            <span
              key={a.id}
              className="inline-flex items-center gap-1.5 rounded-md bg-zinc-100 px-2 py-0.5 text-[11px] dark:bg-zinc-800"
            >
              <span>📎</span>
              <span className="font-mono">{a.name}</span>
              <span className="text-zinc-400">{fmtSize(a.bytes)}</span>
              <button
                onClick={() =>
                  setAttachments((cur) => cur.filter((x) => x.id !== a.id))
                }
                className="opacity-50 hover:opacity-100"
                aria-label="Remove attachment"
              >
                ×
              </button>
            </span>
          ))}
        </div>
      )}

      <div className="relative">
        <textarea
          ref={taRef}
          value={text}
          onChange={(e) => updateText(e.target.value, e.target.selectionStart)}
          onKeyDown={onKeyDown}
          placeholder={placeholder}
          spellCheck={false}
          className="block w-full resize-none bg-transparent px-3 py-2.5 text-[14px] leading-relaxed outline-none placeholder:text-zinc-400"
          rows={3}
        />

        {picker && items.length > 0 && (
          <div className="absolute bottom-full left-2 z-10 mb-1 w-72 overflow-hidden rounded-md border border-zinc-200 bg-white shadow-lg dark:border-zinc-700 dark:bg-zinc-900">
            <div className="border-b border-zinc-100 bg-zinc-50 px-2 py-1 text-[10px] font-semibold uppercase tracking-wider text-zinc-500 dark:border-zinc-800 dark:bg-zinc-950">
              {picker.kind === "cmd" ? "Commands" : "Mention"} · {items.length}
            </div>
            <ul className="max-h-56 overflow-y-auto">
              {items.map((item, i) => {
                const active = i === picker.cursor;
                if (picker.kind === "cmd") {
                  const c = item as PromptCmd;
                  return (
                    <li
                      key={c.name}
                      onMouseDown={(e) => {
                        e.preventDefault();
                        insertChoice(i);
                      }}
                      onMouseEnter={() =>
                        setPicker((p) => (p ? { ...p, cursor: i } : p))
                      }
                      className={`cursor-pointer px-2 py-1.5 text-[12px] ${
                        active
                          ? "bg-violet-100 dark:bg-violet-900/30"
                          : "hover:bg-zinc-50 dark:hover:bg-zinc-800"
                      }`}
                    >
                      <div className="font-mono font-medium text-violet-700 dark:text-violet-300">
                        {c.name}
                      </div>
                      <div className="text-[11px] text-zinc-500">{c.hint}</div>
                    </li>
                  );
                }
                const m = item as PromptMention;
                return (
                  <li
                    key={m.id}
                    onMouseDown={(e) => {
                      e.preventDefault();
                      insertChoice(i);
                    }}
                    onMouseEnter={() =>
                      setPicker((p) => (p ? { ...p, cursor: i } : p))
                    }
                    className={`flex cursor-pointer items-center gap-2 px-2 py-1.5 text-[12px] ${
                      active
                        ? "bg-violet-100 dark:bg-violet-900/30"
                        : "hover:bg-zinc-50 dark:hover:bg-zinc-800"
                    }`}
                  >
                    <span
                      className="h-2 w-2 rounded-full"
                      style={{ backgroundColor: colors[m.kind] ?? "#71717a" }}
                    />
                    <span className="font-medium">{m.name}</span>
                    <span className="ml-auto text-[10px] uppercase tracking-wider text-zinc-400">
                      {m.kind}
                    </span>
                  </li>
                );
              })}
            </ul>
          </div>
        )}
      </div>

      <div className="flex items-center gap-2 border-t border-zinc-200 bg-zinc-50/60 px-3 py-2 dark:border-zinc-800 dark:bg-zinc-900/40">
        <Tooltip content="Drop files here, or click">
          <Button
            variant="ghost"
            size="sm"
            className="shrink-0"
            onClick={() => {
              /* host can wire its own file picker; default no-op */
            }}
          >
            📎 attach
          </Button>
        </Tooltip>
        <div className="ml-2 flex min-w-0 items-center gap-1.5 overflow-hidden">
          <div className="h-1.5 w-24 shrink overflow-hidden rounded-full bg-zinc-200 dark:bg-zinc-700">
            <div
              className="h-full rounded-full transition-all"
              style={{ width: `${ratio * 100}%`, backgroundColor: meterColor }}
            />
          </div>
          <span className="font-mono text-[11px]" style={{ color: meterColor }}>
            {fmtTokens(tokens)} / {fmtTokens(budgetTokens)}
          </span>
        </div>
        <div className="ml-auto flex shrink-0 items-center gap-2">
          {showHint && (
            <span className="hidden text-[10px] text-zinc-500 sm:inline">
              <kbd className="rounded border border-zinc-300 bg-zinc-50 px-1 py-0.5 font-mono text-[9px] text-zinc-700 dark:border-zinc-700 dark:bg-zinc-800 dark:text-zinc-300">
                ⌘
              </kbd>{" "}
              +{" "}
              <kbd className="rounded border border-zinc-300 bg-zinc-50 px-1 py-0.5 font-mono text-[9px] text-zinc-700 dark:border-zinc-700 dark:bg-zinc-800 dark:text-zinc-300">
                Enter
              </kbd>{" "}
              to send
            </span>
          )}
          <Button color="violet" size="sm" className="shrink-0" onClick={submit}>
            send →
          </Button>
        </div>
      </div>
    </div>
  );
}

function fmtTokens(n: number): string {
  if (n < 1000) return `${n}`;
  return `${(n / 1000).toFixed(1)}k`;
}

function fmtSize(b: number): string {
  if (b < 1024) return `${b} B`;
  if (b < 1024 * 1024) return `${(b / 1024).toFixed(0)} KB`;
  return `${(b / 1024 / 1024).toFixed(1)} MB`;
}

export { PromptInput } from "./PromptInput";
export type {
  PromptInputProps,
  PromptCmd,
  PromptMention,
  PromptAttachment,
} from "./PromptInput";

import {
    CheckboxGroup,
    RadioGroup,
    Text,
    Textarea,
} from '@particle-academy/react-fancy';
import type { Question } from '../types';

export type AnswerValue =
    | { kind: 'option_id'; value: number }
    | { kind: 'option_ids'; value: number[] }
    | { kind: 'text'; value: string }
    | null;

export interface QuestionRendererProps {
    question: Question;
    value: AnswerValue;
    onChange: (next: AnswerValue) => void;
    disabled?: boolean;
}

export function QuestionRenderer({
    question,
    value,
    onChange,
    disabled,
}: QuestionRendererProps) {
    const options = question.options ?? [];

    if (question.type === 'multiple_choice' || question.type === 'true_false') {
        const selected =
            value?.kind === 'option_id' ? String(value.value) : undefined;

        return (
            <div className="grid gap-3">
                <Text weight="semibold" className="!text-base">
                    {question.prompt}
                </Text>
                <RadioGroup<string>
                    name={`q-${question.id}`}
                    list={options.map((o) => ({ value: String(o.id), label: o.label }))}
                    value={selected}
                    onValueChange={(next) =>
                        onChange({ kind: 'option_id', value: Number(next) })
                    }
                    disabled={disabled}
                />
            </div>
        );
    }

    if (question.type === 'multiple_select') {
        const selected =
            value?.kind === 'option_ids' ? value.value.map(String) : undefined;

        return (
            <div className="grid gap-3">
                <Text weight="semibold" className="!text-base">
                    {question.prompt}
                </Text>
                <Text size="sm" color="muted">
                    Select all that apply.
                </Text>
                <CheckboxGroup<string>
                    name={`q-${question.id}`}
                    list={options.map((o) => ({ value: String(o.id), label: o.label }))}
                    value={selected}
                    onValueChange={(next) =>
                        onChange({ kind: 'option_ids', value: next.map(Number) })
                    }
                    disabled={disabled}
                />
            </div>
        );
    }

    // short_answer
    const text = value?.kind === 'text' ? value.value : '';
    return (
        <div className="grid gap-3">
            <Text weight="semibold" className="!text-base">
                {question.prompt}
            </Text>
            <Textarea
                value={text}
                onChange={(e) =>
                    onChange({
                        kind: 'text',
                        value: (e.target as HTMLTextAreaElement).value,
                    })
                }
                disabled={disabled}
                rows={4}
                placeholder="Type your answer here…"
            />
        </div>
    );
}

export function answerValueToPayload(
    questionId: number,
    value: AnswerValue,
): { question_id: number; answer: unknown } {
    if (!value) return { question_id: questionId, answer: null };
    switch (value.kind) {
        case 'option_id':
            return { question_id: questionId, answer: { option_id: value.value } };
        case 'option_ids':
            return { question_id: questionId, answer: { option_ids: value.value } };
        case 'text':
            return { question_id: questionId, answer: { text: value.value } };
    }
}

import { cn, Badge } from "@particle-academy/react-fancy";

export interface RankProgressProps {
  /** Current tier/rank key. */
  tier: string;
  /** The next tier (omit / null at the top tier). */
  nextTier?: string | null;
  /** Progress toward the next tier (e.g. team volume, active referrals). */
  value: number;
  /** Threshold that unlocks `nextTier`. */
  target?: number | null;
  unit?: string;
  className?: string;
}

/** Current rank + a progress bar toward the next tier's qualification threshold. */
export function RankProgress({ tier, nextTier, value, target, unit, className }: RankProgressProps) {
  const hasTarget = typeof target === "number" && target > 0 && nextTier != null;
  const pct = hasTarget ? Math.max(0, Math.min(100, (value / target) * 100)) : 100;
  const remaining = hasTarget ? Math.max(0, target - value) : 0;
  const suffix = unit ? ` ${unit}` : "";

  return (
    <div data-fancy-mlm="rank-progress" className={cn("fancy-mlm-rank", className)}>
      <div className="fancy-mlm-rank__head">
        <Badge variant="soft">{tier}</Badge>
        {hasTarget ? (
          <span className="fancy-mlm-rank__next">→ {nextTier}</span>
        ) : (
          <span className="fancy-mlm-rank__muted">Top tier</span>
        )}
      </div>

      <div
        className="fancy-mlm-rank__bar"
        role="progressbar"
        aria-valuenow={Math.round(pct)}
        aria-valuemin={0}
        aria-valuemax={100}
        data-mlm-rank-pct={Math.round(pct)}
      >
        <div className="fancy-mlm-rank__fill" style={{ width: `${pct}%` }} />
      </div>

      {hasTarget ? (
        <div className="fancy-mlm-rank__meta">
          {value.toLocaleString()} / {target.toLocaleString()}
          {suffix} · {remaining.toLocaleString()} to {nextTier}
        </div>
      ) : null}
    </div>
  );
}

import { forwardRef, useEffect, useRef, useState } from "react";
import { cn } from "../../utils/cn";
import type { StickyNoteColor, StickyNoteProps } from "./StickyNote.types";

// Preset paper colors → bg + text classes. An arbitrary CSS color string
// falls through to an inline `background` (text stays a dark ink tone).
const colorClasses: Record<StickyNoteColor, string> = {
  yellow: "bg-amber-100 text-amber-950 dark:bg-amber-200 dark:text-amber-950",
  blue: "bg-sky-100 text-sky-950 dark:bg-sky-200 dark:text-sky-950",
  green: "bg-emerald-100 text-emerald-950 dark:bg-emerald-200 dark:text-emerald-950",
  pink: "bg-pink-100 text-pink-950 dark:bg-pink-200 dark:text-pink-950",
  violet: "bg-violet-100 text-violet-950 dark:bg-violet-200 dark:text-violet-950",
};

const isPreset = (c: string): c is StickyNoteColor => c in colorClasses;

/**
 * A sticky note — paper-styled, with optional inline text editing.
 *
 * Presentational primitive only: it owns the note's look and its editable
 * text. Positioning, dragging, resizing, and z-order are the consumer's job
 * (e.g. `fancy-whiteboard`'s `<Board>` places it in world space;
 * `fancy-artboard`'s `<ArtBoard.Note>` positions it absolutely).
 *
 *   <StickyNote value={text} onChange={setText} color="yellow" rotate={-2} />
 */
export const StickyNote = forwardRef<HTMLDivElement, StickyNoteProps>(
  (
    {
      value,
      defaultValue,
      onChange,
      color = "yellow",
      rotate = 0,
      width = 180,
      height = "auto",
      selected = false,
      editable = true,
      autoFocus = false,
      id,
      children,
      className,
      style,
    },
    ref,
  ) => {
    const isControlled = value !== undefined;
    const [internal, setInternal] = useState(defaultValue ?? "");
    const text = isControlled ? value : internal;
    const editRef = useRef<HTMLDivElement>(null);

    // Push text into the contentEditable node only when it differs AND the node
    // isn't focused — editing in place must not yank the caret to the start.
    useEffect(() => {
      const el = editRef.current;
      if (el && document.activeElement !== el && el.textContent !== text) {
        el.textContent = text ?? "";
      }
    }, [text]);

    // Focus + caret-to-end when editing turns on (consumer "enter edit" gesture).
    useEffect(() => {
      if (!editable || !autoFocus) return;
      const el = editRef.current;
      if (!el) return;
      el.focus();
      const range = document.createRange();
      range.selectNodeContents(el);
      range.collapse(false);
      const sel = window.getSelection();
      sel?.removeAllRanges();
      sel?.addRange(range);
    }, [editable, autoFocus]);

    const commit = () => {
      const next = editRef.current?.textContent ?? "";
      if (next === text) return;
      if (!isControlled) setInternal(next);
      onChange?.(next);
    };

    const preset = isPreset(color);
    const content =
      children != null ? (
        children
      ) : editable ? (
        <div
          ref={editRef}
          contentEditable
          suppressContentEditableWarning
          spellCheck={false}
          role="textbox"
          aria-multiline="true"
          className="outline-none whitespace-pre-wrap break-words min-h-[1.4em]"
          onBlur={commit}
          onKeyDown={(e) => {
            if (e.key === "Escape") e.currentTarget.blur();
          }}
        >
          {text}
        </div>
      ) : (
        <div className="whitespace-pre-wrap break-words">{text}</div>
      );

    return (
      <div
        ref={ref}
        id={id}
        data-react-fancy-sticky=""
        className={cn(
          "rounded-sm p-3.5 text-sm leading-relaxed shadow-[0_2px_8px_rgba(0,0,0,0.12),0_1px_2px_rgba(0,0,0,0.08)]",
          preset ? colorClasses[color] : "text-zinc-900",
          selected && "ring-2 ring-blue-500 ring-offset-1",
          className,
        )}
        style={{
          width,
          height,
          transform: rotate ? `rotate(${rotate}deg)` : undefined,
          ...(preset ? null : { background: color }),
          ...style,
        }}
      >
        {content}
      </div>
    );
  },
);

StickyNote.displayName = "StickyNote";

import type { CSSProperties, ReactNode } from "react";

/** Built-in paper colors. Any CSS color string is also accepted. */
export type StickyNoteColor = "yellow" | "blue" | "green" | "pink" | "violet";

export interface StickyNoteProps {
  /** Note text (controlled). */
  value?: string;
  /** Initial text when uncontrolled. */
  defaultValue?: string;
  /** Fires when the edited text is committed (on blur). */
  onChange?: (text: string) => void;
  /** Paper color — one of the presets, or any CSS color string. Default `"yellow"`. */
  color?: StickyNoteColor | (string & {});
  /** Rotation in degrees. Default `0`. */
  rotate?: number;
  /** Width as px number or any CSS length. Default `180`. */
  width?: number | string;
  /** Height as px number or any CSS length. Default `"auto"`. */
  height?: number | string;
  /** Selected styling (focus ring). */
  selected?: boolean;
  /** Allow inline editing of the text. Default `true`. */
  editable?: boolean;
  /**
   * Focus the editable region (caret at end) when it becomes editable. Lets a
   * consumer's "enter edit mode" gesture drop straight into typing. Default `false`.
   */
  autoFocus?: boolean;
  /**
   * Stable handle — also emitted as the element `id`. Lets agents and
   * selectors target a specific note without guessing the DOM.
   */
  id?: string;
  /** Static content; when provided, overrides the editable text. */
  children?: ReactNode;
  className?: string;
  style?: CSSProperties;
}

import { Popover } from "../Popover";
import { Button } from "../Button";

/**
 * ReasonTag — wraps any value with a small affordance that reveals the
 * agent's reasoning, sources, and confidence on hover or click.
 *
 *   <ReasonTag
 *     value="$1.4M"
 *     reason="Projected Q3 ARR after stacking renewals."
 *     confidence={0.91}
 *     sources={[{ label: "Q2 actuals · CRM export" }]}
 *     by="Forecaster"
 *   />
 *
 * Three visual styles:
 *   • "dot"       — value with a tiny coloured dot (default, subtle)
 *   • "underline" — dotted underline + trailing "?"
 *   • "chip"      — full coloured pill (loud)
 *
 * Confidence drives the colour via three tiers (high / medium / low),
 * so a quick visual scan tells the human which suggestions deserve a
 * second look without opening any tooltips.
 *
 * `pinned` swaps the popover for an inline annotation slot — useful
 * when explainability should always be visible, not buried in a hover.
 */
export type ReasonTagSource = { label: string; href?: string };

export type ReasonTagTheme = "dot" | "underline" | "chip";

export interface ReasonTagProps {
  /** The value the tag wraps — usually a number, label, or short phrase. */
  value: React.ReactNode;
  /** Free-text rationale shown in the popover / inline annotation. */
  reason: string;
  /** 0..1 confidence. Drives the tier colour. Defaults to 1. */
  confidence?: number;
  /** Optional list of sources (label + optional href). */
  sources?: ReasonTagSource[];
  /** Optional author / agent name shown in the popover header. */
  by?: string;
  /** Visual treatment for the trigger. */
  theme?: ReasonTagTheme;
  /**
   * When true, the popover is replaced with an always-visible inline
   * annotation below the value.
   */
  pinned?: boolean;
  /** Called when the user hits the "ask follow-up" action. */
  onFollowUp?: () => void;
  /** Optional className applied to the trigger element. */
  className?: string;
}

const CONFIDENCE_TIERS: Array<{ min: number; color: string; label: string }> = [
  { min: 0.85, color: "#10b981", label: "high" },
  { min: 0.6, color: "#f59e0b", label: "medium" },
  { min: 0, color: "#ef4444", label: "low" },
];

function tier(c: number) {
  return CONFIDENCE_TIERS.find((t) => c >= t.min) ?? CONFIDENCE_TIERS[2];
}

export function ReasonTag({
  value,
  reason,
  confidence = 1,
  sources = [],
  by,
  theme = "dot",
  pinned = false,
  onFollowUp,
  className,
}: ReasonTagProps) {
  const t = tier(confidence);

  const trigger =
    theme === "chip" ? (
      <span
        className={`inline-flex cursor-help items-center gap-1 rounded-full px-2 py-0.5 text-[12px] font-medium ${className ?? ""}`}
        style={{ backgroundColor: t.color + "22", color: t.color }}
      >
        <span
          className="h-1.5 w-1.5 rounded-full"
          style={{ backgroundColor: t.color }}
        />
        {value}
        <span className="text-[10px] opacity-70">?</span>
      </span>
    ) : theme === "underline" ? (
      <span
        className={`cursor-help underline decoration-dotted underline-offset-2 ${className ?? ""}`}
        style={{ textDecorationColor: t.color }}
      >
        {value}
        <span
          className="ml-0.5 font-mono text-[10px]"
          style={{ color: t.color }}
        >
          ?
        </span>
      </span>
    ) : (
      <span className={`inline-flex cursor-help items-baseline gap-1 ${className ?? ""}`}>
        <span className="font-medium">{value}</span>
        <span
          className="inline-block h-1.5 w-1.5 rounded-full align-middle"
          style={{ backgroundColor: t.color }}
          title="reason available"
        />
      </span>
    );

  if (pinned) {
    return (
      <span className="inline-flex flex-col items-start gap-0.5 align-top">
        {trigger}
        <span
          className="block max-w-[280px] rounded border-l-2 pl-2 text-[11px] leading-snug text-zinc-600 dark:text-zinc-300"
          style={{ borderColor: t.color }}
        >
          {reason}
        </span>
      </span>
    );
  }

  return (
    <Popover hover>
      <Popover.Trigger>{trigger}</Popover.Trigger>
      <Popover.Content>
        <div className="w-72 space-y-2 text-sm">
          <div className="flex items-baseline gap-2">
            <span
              className="text-[10px] font-semibold uppercase tracking-wider"
              style={{ color: t.color }}
            >
              {t.label} confidence · {(confidence * 100).toFixed(0)}%
            </span>
            {by && (
              <span className="ml-auto font-mono text-[10px] text-zinc-400">
                @{by}
              </span>
            )}
          </div>
          <p className="text-[13px] leading-snug text-zinc-700 dark:text-zinc-200">
            {reason}
          </p>
          {sources.length > 0 && (
            <div>
              <div className="text-[10px] uppercase tracking-wider text-zinc-400">
                sources
              </div>
              <ul className="mt-0.5 space-y-0.5 text-[12px]">
                {sources.map((s, i) => (
                  <li key={i}>
                    {s.href ? (
                      <a className="text-violet-600 hover:underline" href={s.href}>
                        {s.label}
                      </a>
                    ) : (
                      <span className="text-zinc-600 dark:text-zinc-300">
                        {s.label}
                      </span>
                    )}
                  </li>
                ))}
              </ul>
            </div>
          )}
          {onFollowUp && (
            <div className="flex justify-end pt-1">
              <Button size="sm" variant="ghost" onClick={onFollowUp}>
                ask follow-up
              </Button>
            </div>
          )}
        </div>
      </Popover.Content>
    </Popover>
  );
}

import { Badge, Breadcrumbs, Icon, Text } from "@particle-academy/react-fancy";
import { statusColor } from "./status-color.js";

export type RepositoryEntry = {
  id: string;
  name: string;
  path: string;
  kind: "file" | "directory" | "symlink" | "submodule";
  size?: number;
  status?: string;
};

export interface RepositoryBrowserProps {
  value: RepositoryEntry[];
  path: string;
  selectedPath?: string;
  onPathChange?: (path: string) => void;
  onSelectedPathChange?: (path: string) => void;
  loading?: boolean;
  className?: string;
}

/** The icon each entry kind gets. A submodule and a symlink are not just files. */
const KIND_ICON: Record<RepositoryEntry["kind"], string> = {
  directory: "folder",
  file: "file",
  symlink: "link",
  submodule: "box",
};

/**
 * One directory of a repository, at a ref.
 *
 * ## Why this is not `<TreeNav>`
 *
 * The shapes look alike; the models are not. `TreeNav` holds a whole tree in
 * memory and expands nodes in place. This browser is **lazy and one level at a
 * time** — `value` is a single directory's contents and `onPathChange` asks the
 * host to fetch the next one. A repository has far more files than anyone wants
 * to load in order to draw one folder, which is exactly why the API is shaped
 * this way.
 *
 * So the primitives here are the ones that actually fit: `<Breadcrumbs>` for
 * the path — hand-rolled `/` separators were the real duplication — `<Icon>`
 * for entry kinds, replacing 📁/📄 emoji that ignored the host's icon set and
 * rendered differently on every platform, and `<Badge>` for status.
 *
 * Reaching for `TreeNav` because the shape resembles a tree would produce a
 * component that cannot do the one thing this one exists for.
 */
export function RepositoryBrowser({
  value,
  path,
  selectedPath,
  onPathChange,
  onSelectedPathChange,
  loading,
  className,
}: RepositoryBrowserProps) {
  const crumbs = path.split("/").filter(Boolean);

  return (
    <section
      className={className}
      data-git-repository-browser=""
      aria-label="Repository browser"
      aria-busy={loading}
    >
      <Breadcrumbs>
        <Breadcrumbs.Item onClick={() => onPathChange?.("")} active={crumbs.length === 0}>
          root
        </Breadcrumbs.Item>
        {crumbs.map((crumb, index) => (
          <Breadcrumbs.Item
            key={`${crumb}-${index}`}
            // The last crumb is where you already are, so it is not a
            // destination — Breadcrumbs renders it as plain text.
            active={index === crumbs.length - 1}
            onClick={() => onPathChange?.(crumbs.slice(0, index + 1).join("/"))}
          >
            {crumb}
          </Breadcrumbs.Item>
        ))}
      </Breadcrumbs>

      <ul>
        {value.map((entry) => (
          <li
            key={entry.id}
            data-git-path={entry.path}
            data-git-entry-kind={entry.kind}
            data-selected={selectedPath === entry.path || undefined}
          >
            <button
              type="button"
              aria-pressed={selectedPath === entry.path}
              onClick={() =>
                entry.kind === "directory" ? onPathChange?.(entry.path) : onSelectedPathChange?.(entry.path)
              }
            >
              <Icon name={KIND_ICON[entry.kind]} size="sm" />
              <Text size="sm">{entry.name}</Text>
              {entry.status && (
                <Badge color={statusColor(entry.status)} variant="soft" size="sm">
                  {entry.status}
                </Badge>
              )}
            </button>
          </li>
        ))}
      </ul>
    </section>
  );
}

import { Badge, Text } from "@particle-academy/react-fancy";
import type { Review } from "@particle-academy/fancy-git";
import { reviewStateColor } from "./status-color.js";

export interface ReviewListProps {
  value: Review[];
  selectedNumber?: number;
  onSelectedNumberChange?: (number: number) => void;
  className?: string;
}

/**
 * Pull / merge requests and their state.
 *
 * A list of selectable rows rather than a `<Table>`: `<Table>` earns its
 * complexity when there are columns to sort and compare, and a review row is
 * one title plus its state. Forcing it into a grid would add sortable headers
 * over data nobody sorts, and lose the whole-row click this surface is for.
 *
 * `<Badge>` does carry its weight — open / merged / closed / draft is exactly
 * the four-way status a badge exists for, and every forge already trains people
 * to read those colours.
 */
export function ReviewList({ value, selectedNumber, onSelectedNumberChange, className }: ReviewListProps) {
  return (
    <section className={className} data-git-review-list="" aria-label="Reviews">
      <ul>
        {value.map((review) => (
          <li
            key={review.id}
            data-git-review-number={review.number}
            data-selected={selectedNumber === review.number || undefined}
          >
            <button
              type="button"
              aria-pressed={selectedNumber === review.number}
              onClick={() => onSelectedNumberChange?.(review.number)}
            >
              <span data-git-review-head="">
                <Text size="sm" className="!font-medium">
                  #{review.number} {review.title}
                </Text>
                <Badge color={reviewStateColor(review.state)} variant="soft" size="sm">
                  {review.state}
                </Badge>
              </span>
              <Text size="xs" className="!text-zinc-500">
                <code>{review.sourceBranch}</code> → <code>{review.targetBranch}</code>
              </Text>
            </button>
          </li>
        ))}
      </ul>
    </section>
  );
}

import { Button, Callout, Input } from "@particle-academy/react-fancy";
import type { RobotsGroup, RobotsModel } from "../model.js";
import { validateRobots } from "../validate.js";
import { IssueList, Section, StringList } from "./internal.js";

export interface RobotsEditorProps {
  /** Controlled robots.txt model. */
  value: RobotsModel;
  /** Fires with the next model on every edit. */
  onChange: (next: RobotsModel) => void;
  /** Hide the inline validation issue list. Default `false`. */
  hideIssues?: boolean;
  className?: string;
}

/**
 * Controlled robots.txt rule builder.
 *
 * Protected-path safety (mirrors the PHP `protect()` rail): paths listed under
 * **Protected paths** are pinned Disallowed for every group and can NEVER be
 * Allowed. The editor:
 *  - renders protected chips in red, labelled "Disallowed everywhere";
 *  - strips a protected path out of any group's Allow list as you protect it;
 *  - flags (via {@link validateRobots}) any protected path still sitting in an
 *    Allow list, so the issue surfaces inline.
 */
export function RobotsEditor({
  value,
  onChange,
  hideIssues,
  className,
}: RobotsEditorProps) {
  const issues = validateRobots(value);

  const patch = (next: Partial<RobotsModel>) => onChange({ ...value, ...next });

  const updateGroup = (index: number, next: Partial<RobotsGroup>) => {
    const groups = value.groups.map((g, i) =>
      i === index ? { ...g, ...next } : g,
    );
    onChange({ ...value, groups });
  };

  const addGroup = () =>
    patch({
      groups: [
        ...value.groups,
        { userAgents: ["*"], allow: [], disallow: [] },
      ],
    });

  const removeGroup = (index: number) =>
    patch({ groups: value.groups.filter((_, i) => i !== index) });

  /** Setting Allow for a group: protected paths are filtered out entirely. */
  const setAllow = (index: number, next: string[]) => {
    const filtered = next.filter((p) => !value.protectedPaths.includes(p));
    updateGroup(index, { allow: filtered });
  };

  /** Protecting a path also removes it from every group's Allow list. */
  const setProtected = (next: string[]) => {
    const protectedSet = new Set(next);
    const groups = value.groups.map((g) => ({
      ...g,
      allow: g.allow.filter((p) => !protectedSet.has(p)),
    }));
    onChange({ ...value, protectedPaths: next, groups });
  };

  return (
    <div className={className} data-x-editor="robots">
      <Section
        title="Protected paths"
        handle="robots-protected"
        action={
          value.protectedPaths.length ? (
            <span style={{ fontSize: "0.75rem", opacity: 0.7 }}>
              Disallowed for every agent · cannot be Allowed
            </span>
          ) : null
        }
      >
        <Callout color="red">
          Paths added here are pinned <strong>Disallow</strong> on every
          user-agent group and can never be marked Allow. This mirrors the
          server-side <code>protect()</code> safety rail.
        </Callout>
        <StringList
          handle="robots-protected"
          values={value.protectedPaths}
          onChange={setProtected}
          placeholder="/admin"
        />
      </Section>

      <Section
        title="Sitemaps"
        handle="robots-sitemaps"
      >
        <StringList
          handle="robots-sitemaps"
          values={value.sitemaps}
          onChange={(sitemaps) => patch({ sitemaps })}
          placeholder="https://example.com/sitemap.xml"
        />
      </Section>

      <Section title="Host" handle="robots-host">
        <Input
          value={value.host ?? ""}
          onValueChange={(host) => patch({ host: host || undefined })}
          placeholder="example.com"
          data-x-input="robots-host"
        />
      </Section>

      <Section
        title="User-agent groups"
        handle="robots-groups"
        action={
          <Button
            type="button"
            variant="ghost"
            onClick={addGroup}
            data-x-add="robots-group"
          >
            Add group
          </Button>
        }
      >
        {value.groups.map((group, i) => (
          <div
            key={i}
            data-x-group={i}
            style={{
              border: "1px solid var(--rf-border, #e5e7eb)",
              borderRadius: "0.5rem",
              padding: "0.75rem",
              display: "flex",
              flexDirection: "column",
              gap: "0.6rem",
            }}
          >
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <strong style={{ fontSize: "0.8rem" }}>Group {i + 1}</strong>
              <Button
                type="button"
                variant="ghost"
                color="red"
                onClick={() => removeGroup(i)}
                data-x-remove={`robots-group:${i}`}
                disabled={value.groups.length <= 1}
              >
                Remove
              </Button>
            </div>
            <StringList
              label="User-agents"
              handle={`robots-ua:${i}`}
              values={group.userAgents}
              onChange={(userAgents) => updateGroup(i, { userAgents })}
              placeholder="*"
            />
            <StringList
              label="Disallow"
              handle={`robots-disallow:${i}`}
              values={group.disallow}
              onChange={(disallow) => updateGroup(i, { disallow })}
              placeholder="/private"
            />
            <StringList
              label="Allow"
              handle={`robots-allow:${i}`}
              values={group.allow}
              onChange={(allow) => setAllow(i, allow)}
              placeholder="/public"
              disallowedValues={value.protectedPaths}
              disallowedReason={(p) =>
                `"${p}" is protected and cannot be Allowed.`
              }
            />
            <div style={{ maxWidth: "12rem" }}>
              <Input
                type="number"
                label="Crawl-delay (s)"
                value={group.crawlDelay != null ? String(group.crawlDelay) : ""}
                onValueChange={(v) =>
                  updateGroup(i, {
                    crawlDelay: v === "" ? undefined : Number(v),
                  })
                }
                data-x-input={`robots-crawldelay:${i}`}
                placeholder="0"
              />
            </div>
          </div>
        ))}
      </Section>

      {hideIssues ? null : <IssueList issues={issues} testid="robots" />}
    </div>
  );
}

import type {
  ExecutorRegistry,
  FlowEdge,
  FlowGraph,
  FlowNode,
  NodeExecutor,
  RunEvent,
} from "../types";
// Both modules are React-free by design — the `/engine` entry must not pull in
// React. Import them directly rather than via the `registry` barrel, which
// re-exports the RegistryNode component.
import { getNodeKind, kindIds } from "../registry/registry";
import { resolveNodePorts } from "../registry/ports";

export type RunOptions = {
  /** Stop the run after this many ms. Default: no timeout. */
  timeoutMs?: number;
  /** Abort signal — host can cancel the run. */
  signal?: AbortSignal;
  /** Initial inputs supplied to entry-point nodes (no incoming edges). */
  initialInputs?: Record<string, Record<string, unknown>>;
  /** Nesting depth — set by `subflow` when it runs a child graph. */
  depth?: number;
};

export type RunResult = {
  ok: boolean;
  /** Outputs collected per node, keyed by node id. */
  outputs: Record<string, unknown>;
  /** Error captured if any node threw. */
  error?: string;
};

/**
 * runFlow — topological execution of a FlowGraph against an ExecutorRegistry.
 *
 * Each node runs once, when all upstream nodes have produced outputs on the
 * connected ports. Decision nodes (or any executor that returns `{ branch:
 * 'true' }`) can short-circuit specific output ports — only edges leaving
 * an "active" port propagate to downstream nodes.
 *
 * Cycles are detected and abort the run with an error.
 *
 * The `onEvent` callback receives a stream of `RunEvent`s — wire it to a
 * status feed, log panel, or store.
 */
export async function runFlow(
  graph: FlowGraph,
  executors: ExecutorRegistry,
  onEvent: (event: RunEvent) => void = () => {},
  options: RunOptions = {},
): Promise<RunResult> {
  const { signal, initialInputs = {}, timeoutMs, depth = 0 } = options;
  const outputs: Record<string, unknown> = {};
  const portValues = new Map<string, unknown>(); // key: `${nodeId}:${portId}`
  const completed = new Set<string>();
  const errors: string[] = [];

  // Topological order via Kahn's algorithm. We allow nodes to run as soon
  // as their incoming edges' source ports have produced values, so the
  // order here is just a deterministic baseline used for cycle detection.
  const order = topoSort(graph);
  if (order === null) {
    const msg = "Cycle detected in flow graph — aborting.";
    onEvent({ type: "run-error", error: msg });
    return { ok: false, outputs, error: msg };
  }

  const incomingByNode = indexIncoming(graph.edges);
  const timer = timeoutMs ? setTimeout(() => errors.push(`Run timed out after ${timeoutMs}ms`), timeoutMs) : null;

  onEvent({ type: "run-start" });

  try {
    for (const node of order) {
      if (signal?.aborted) throw new Error("aborted");
      if (errors.length) break;

      const incoming = incomingByNode.get(node.id) ?? [];

      // Run a node once any upstream branch reaches it. We iterate in
      // topological order, so by the time we reach this node every upstream
      // node has been processed — each incoming edge is therefore *settled*
      // (active or dead, never still-pending). Requiring ALL incoming edges to
      // be active wrongly skipped MERGE POINTS: when a Decision routes down one
      // branch, the other branch's edge stays dead forever, so an `every` check
      // skipped the shared continuation node and halted the run after the first
      // branch (#1). Run when AT LEAST ONE incoming edge is active —
      // collectInputs() only reads from the active ones. A genuine parallel
      // join still works: in topo order both of its inputs are already active.
      if (incoming.length > 0) {
        const anyActive = incoming.some((e) => portValues.has(`${e.source}:${e.sourceHandle ?? "out"}`));
        if (!anyActive) {
          onEvent({ type: "node-status", nodeId: node.id, status: "idle", text: "skipped" });
          continue;
        }
      }

      // Notes/annotations + layout (lane/pool) nodes are visual only — never
      // executed and never fed to runners. Their config (a note's text, a lane's
      // title) stays in the document for editors + MCP tools, but the engine
      // walks straight past them. Edges cross lanes freely, so grouping never
      // affects topology.
      const visualKind = getNodeKind(node.type ?? "");
      const isLayout = visualKind?.category === "layout";
      const isAnnotation = node.type === "note" || visualKind?.category === "annotation";
      if (isLayout || isAnnotation) {
        onEvent({
          type: "node-status",
          nodeId: node.id,
          status: "idle",
          text: isLayout ? "lane" : "annotation",
        });
        continue;
      }

      onEvent({ type: "node-status", nodeId: node.id, status: "running" });

      const inputs = collectInputs(node, incoming, portValues, initialInputs);
      const exec = pickExecutor(executors, node);
      if (!exec) {
        const msg = `No executor registered for kind=${node.type}`;
        errors.push(msg);
        onEvent({ type: "node-status", nodeId: node.id, status: "error", text: msg });
        onEvent({ type: "log", nodeId: node.id, level: "error", message: msg });
        break;
      }

      try {
        const result = await Promise.resolve(
          exec({
            node,
            inputs,
            abort: (reason) => { throw new Error(reason ?? "aborted"); },
            emit: onEvent,
            depth,
          }),
        );
        outputs[node.id] = result;

        // Decide which output ports were activated. Three conventions:
        //  1) If result is `{ __port: "out", value: x }`, only that port emits.
        //  2) If result has `branch: <portId>`, only that port emits (decision sugar).
        //  3) Otherwise, the value is published on every declared output port.
        const activated = activatedPorts(node, result);
        for (const portId of activated.ports) {
          portValues.set(`${node.id}:${portId}`, activated.value);
          onEvent({ type: "node-output", nodeId: node.id, portId, value: activated.value });
        }
        completed.add(node.id);
        onEvent({ type: "node-status", nodeId: node.id, status: "done" });
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        errors.push(msg);
        onEvent({ type: "node-status", nodeId: node.id, status: "error", text: msg });
        onEvent({ type: "log", nodeId: node.id, level: "error", message: msg });
        break;
      }
    }
  } finally {
    if (timer) clearTimeout(timer);
  }

  const ok = errors.length === 0;
  onEvent({ type: "run-end", ok });
  return ok ? { ok, outputs } : { ok, outputs, error: errors[0] };
}

function indexIncoming(edges: FlowEdge[]): Map<string, FlowEdge[]> {
  const map = new Map<string, FlowEdge[]>();
  for (const e of edges) {
    const list = map.get(e.target) ?? [];
    list.push(e);
    map.set(e.target, list);
  }
  return map;
}

function topoSort(graph: FlowGraph): FlowNode[] | null {
  const inDegree = new Map<string, number>();
  for (const n of graph.nodes) inDegree.set(n.id, 0);
  for (const e of graph.edges) inDegree.set(e.target, (inDegree.get(e.target) ?? 0) + 1);
  const queue: string[] = [];
  for (const [id, d] of inDegree) if (d === 0) queue.push(id);
  const ordered: string[] = [];
  while (queue.length) {
    const id = queue.shift()!;
    ordered.push(id);
    for (const e of graph.edges) {
      if (e.source !== id) continue;
      const next = (inDegree.get(e.target) ?? 0) - 1;
      inDegree.set(e.target, next);
      if (next === 0) queue.push(e.target);
    }
  }
  if (ordered.length !== graph.nodes.length) return null;
  const byId = new Map(graph.nodes.map((n) => [n.id, n]));
  return ordered.map((id) => byId.get(id)!).filter(Boolean);
}

function collectInputs(
  node: FlowNode,
  incoming: FlowEdge[],
  portValues: Map<string, unknown>,
  initial: Record<string, Record<string, unknown>>,
): Record<string, unknown> {
  const inputs: Record<string, unknown> = { ...(initial[node.id] ?? {}) };
  for (const e of incoming) {
    const portId = e.targetHandle ?? "in";
    const key = `${e.source}:${e.sourceHandle ?? "out"}`;
    // A branch that never fired has no entry in portValues. Assigning its
    // `undefined` would CLOBBER the value the branch that DID fire already
    // contributed on this same handle — emptying every merge point downstream
    // of a decision, silently, with the run still reporting success.
    //
    // This is the other half of the merge-point bug above: that fix stopped the
    // shared continuation node being skipped, but it still arrived with nothing
    // whenever a later inactive edge happened to be last in `incoming`.
    if (!portValues.has(key)) continue;
    inputs[portId] = portValues.get(key);
  }
  return inputs;
}

function pickExecutor(
  executors: ExecutorRegistry,
  node: FlowNode,
): NodeExecutor | undefined {
  if (executors[node.id]) return executors[node.id];
  if (node.type && executors[node.type]) return executors[node.type];

  // Try every id the kind answers to. Kinds are namespaced (`@fancy/switch_case`)
  // while a host may have bound its executor under the bare name it used before
  // — or vice versa. Without this, the rename would silently stop matching and
  // the node would fall through to `*` or simply not run: a breaking change
  // wearing the costume of a rename.
  const kind = node.type ? getNodeKind(node.type) : null;
  if (kind) {
    for (const id of kindIds(kind)) {
      if (executors[id]) return executors[id];
    }
  }

  return executors["*"];
}

function activatedPorts(node: FlowNode, result: unknown): { ports: string[]; value: unknown } {
  if (result && typeof result === "object") {
    const r = result as Record<string, unknown>;
    if (typeof r.__port === "string") {
      return { ports: [r.__port], value: r.value };
    }
    if (typeof r.branch === "string") {
      return { ports: [r.branch], value: r.value ?? r };
    }
  }
  // Resolve through the shared helper so the ports the runtime activates are
  // the same ones the canvas drew — including config-driven ports, which the
  // node's `data` does not carry. Falls back to a lone `out` when a node
  // declares nothing.
  const kind = getNodeKind((node.data as any)?.kind ?? node.type ?? "") ?? undefined;
  const declared = resolveNodePorts(node, kind).outputs?.map((p) => p.id);
  return { ports: declared?.length ? declared : ["out"], value: result };
}

/**
 * Engine-agnostic scene description.
 *
 * A scene is plain JSON-serializable data. Adapters consume it to render the
 * scene into a concrete engine — DOM, BabylonJS, three.js, native canvas, etc.
 * The same `Scene` should produce a recognizably similar result on every
 * supported engine.
 */

export type WidgetSpec =
  | KpiSpec
  | ChartSpec
  | KanbanSpec
  | TableSpec
  | ProfileSpec
  | CalloutSpec
  | FormSpec
  | ActionSpec
  | TimelineSpec
  | CodeSpec
  | ImageSpec
  | TextSpec
  | DemoPageSpec
  | ScreenSpec;

export interface KpiSpec {
  kind: "kpi";
  label: string;
  value: string;
  delta?: string;
  trend?: "up" | "down" | "flat";
}

export interface ChartSpec {
  kind: "chart";
  title: string;
  variant: "line" | "bar" | "area";
  series: number[];
  color?: string;
}

export interface KanbanSpec {
  kind: "kanban";
  columns: { title: string; cards: string[] }[];
}

export interface TableSpec {
  kind: "table";
  title: string;
  columns: string[];
  rows: (string | number)[][];
}

export interface ProfileSpec {
  kind: "profile";
  name: string;
  role: string;
  initials: string;
  status?: "online" | "away" | "offline";
}

export interface CalloutSpec {
  kind: "callout";
  tone: "info" | "success" | "warning" | "danger";
  title: string;
  body: string;
}

export interface FormSpec {
  kind: "form";
  title: string;
  fields: { id: string; label: string; type: "text" | "switch" | "number" }[];
}

export interface ActionSpec {
  kind: "action";
  title: string;
  buttons: { label: string; variant?: "primary" | "secondary" | "ghost" }[];
}

export interface TimelineSpec {
  kind: "timeline";
  title: string;
  events: { at: string; label: string }[];
}

export interface CodeSpec {
  kind: "code";
  title: string;
  language: string;
  code: string;
}

export interface ImageSpec {
  kind: "image";
  src: string;
  alt: string;
  caption?: string;
}

export interface TextSpec {
  kind: "text";
  heading: string;
  body: string;
}

export interface DemoPageSpec {
  kind: "demoPage";
  name: string;
  description: string;
  path: string;
  accent: string;
  category: string;
}

/**
 * A 3D-native widget — a screen-shaped panel with a bezel frame, status LED,
 * and optional 2D content drawn into the screen surface. Designed to feel
 * like a hardware display in a 3D scene.
 */
export interface ScreenSpec {
  kind: "screen";
  /** Screen contents — either a static label or a paint callback that draws
   *  onto a 2D context sized to the screen's inner area. */
  content:
    | { type: "label"; title: string; subtitle?: string }
    | { type: "image"; src: string; alt?: string }
    | { type: "paint"; paint: (ctx: CanvasRenderingContext2D, w: number, h: number) => void };
  /** Bezel color (CSS hex). Defaults to a dark frame. */
  bezel?: string;
  /** Bezel thickness in pixels, scaled with the screen's pixel size. */
  bezelThickness?: number;
  /** Power state — controls the LED + screen brightness. */
  on?: boolean;
  /** Background fill color when the content does not fill the screen. */
  background?: string;
  /** Brightness multiplier, 0..1. Defaults to 1 when on, 0.05 when off. */
  brightness?: number;
}

export interface SceneNode {
  id: string;
  position: { x: number; y: number; z?: number };
  size?: { w: number; h: number };
  widget: WidgetSpec;
}

export interface SceneEdge {
  id: string;
  from: string;
  to: string;
  label?: string;
  curve?: "bezier" | "step" | "straight";
  animated?: boolean;
}

export interface Scene {
  nodes: SceneNode[];
  edges: SceneEdge[];
}

/**
 * A WidgetAdapter renders one WidgetSpec for one engine. Each engine ships
 * its own adapter; the scene data does not change.
 *
 * The DOM adapter returns a React element. A BabylonJS adapter returns a
 * `Mesh`. A three.js adapter would return an `Object3D`.
 */
export interface WidgetAdapter<T> {
  render(spec: WidgetSpec, ctx: AdapterContext): T;
}

export interface AdapterContext {
  /** Notify the host when the widget requests selection. */
  onSelect?: (id: string) => void;
  /** The id of the node this widget belongs to. */
  nodeId: string;
  /** Whether the node is currently selected — adapters may render an outline. */
  selected: boolean;
}

let _seq = 1000;
export function nextId(prefix: string): string {
  _seq += 1;
  return `${prefix}-${_seq}`;
}

/**
 * Convenience: walk a Scene and call the adapter on every node.
 *
 * Engine-agnostic — every adapter (DOM, Babylon, three) can share it. The
 * host is responsible for placing the returned render results inside its
 * scene graph.
 */
export function renderScene<T>(
  scene: Scene,
  adapter: WidgetAdapter<T>,
  ctxFor: (node: SceneNode) => AdapterContext
): { node: SceneNode; rendered: T }[] {
  return scene.nodes.map((node) => ({ node, rendered: adapter.render(node.widget, ctxFor(node)) }));
}

import { useEffect, useMemo, type CSSProperties, type ReactNode } from "react";
import { ScreenContext, type ScreenContextValue } from "./Screen.context";
import { useScreenSystem } from "./ScreenSystem.context";
import { ScreenSystem } from "./ScreenSystem";
import { renderSchema } from "./schema";
import type { ScreenBodyProps, ScreenProps } from "./Screen.types";

function ScreenBody({ children, className }: ScreenBodyProps) {
  return <div data-fancy-screens-body="" className={className}>{children}</div>;
}
ScreenBody.displayName = "Screen.Body";

/**
 * Containerized application surface. Registers with the enclosing
 * `<Screen.System>` so agents and presence layers can enumerate and
 * target it.
 *
 * Supports two render modes:
 *   - JSX children  — pass any React tree
 *   - schema prop   — agent-emitted JSON, rendered via the schema registry
 *
 * Children win if both are provided.
 */
function ScreenRoot({ id, title, children, schema, className }: ScreenProps) {
  const system = useScreenSystem();

  useEffect(() => {
    system.registerScreen({
      id,
      title,
      lifecycle: "active",
      storeKeys: [],
      lastActiveAt: Date.now(),
    });
    return () => system.unregisterScreen(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  // Patch title without remounting the registry entry.
  useEffect(() => {
    if (title !== undefined) system.updateScreen(id, { title });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id, title]);

  // Read the live agentActivity for this screen so we can apply a CSS
  // class while it's set. Subscribers (e.g. agent-integrations) push
  // updates via system.updateScreen(id, { agentActivity }).
  const meta = system.registry.get(id);
  const agentActivity = meta?.agentActivity;

  const ctx = useMemo<ScreenContextValue>(
    () => ({ id, title, lifecycle: "active" }),
    [id, title],
  );

  const classes = [
    className,
    agentActivity ? "agent-focused-element" : null,
  ].filter(Boolean).join(" ");

  const style: CSSProperties | undefined = agentActivity?.agentColor
    ? ({ ["--agent-color" as unknown as keyof CSSProperties]: agentActivity.agentColor } as CSSProperties)
    : undefined;

  const body = children ?? (schema ? renderSchema(schema) : null);

  return (
    <ScreenContext.Provider value={ctx}>
      <div
        data-fancy-screens-screen=""
        data-screen-id={id}
        className={classes || undefined}
        style={style}
      >
        {body}
      </div>
    </ScreenContext.Provider>
  );
}

ScreenRoot.displayName = "Screen";

export const Screen = Object.assign(ScreenRoot, {
  Body: ScreenBody,
  System: ScreenSystem,
});

export type { ScreenProps, ScreenBodyProps } from "./Screen.types";

import { useMemo, useRef, useState, type ReactNode } from "react";
import { ScreenSystemContext, type ScreenSystemValue } from "./ScreenSystem.context";
import type { RegisteredStore, ScreenMeta } from "./Screen.types";

interface ScreenSystemProps {
  children?: ReactNode;
}

/**
 * Root provider for fancy-screens. Wrap your app once. Owns the screen
 * registry and a Map of registered Zustand stores. Without this,
 * `<Screen>` and `useScreens()` will throw.
 */
export function ScreenSystem({ children }: ScreenSystemProps) {
  const registryRef = useRef<Map<string, ScreenMeta>>(new Map());
  const storesRef = useRef<Map<string, RegisteredStore>>(new Map());
  const [registryVersion, setRegistryVersion] = useState(0);

  const value = useMemo<ScreenSystemValue>(() => {
    const bump = () => setRegistryVersion((v) => v + 1);
    return {
      registry: registryRef.current,
      registryVersion,
      stores: storesRef.current,
      registerScreen: (meta) => {
        registryRef.current.set(meta.id, meta);
        bump();
      },
      updateScreen: (id, patch) => {
        const existing = registryRef.current.get(id);
        if (!existing) return;
        registryRef.current.set(id, { ...existing, ...patch });
        bump();
      },
      unregisterScreen: (id) => {
        registryRef.current.delete(id);
        // Drop any stores registered to this screen so the maps don't drift.
        const prefix = `${id}.`;
        for (const key of storesRef.current.keys()) {
          if (key.startsWith(prefix)) storesRef.current.delete(key);
        }
        bump();
      },
      registerStore: (key, store) => {
        storesRef.current.set(key, store);
        // Patch the storeKeys array on the owning screen so consumers can
        // enumerate stores without scanning the global map.
        const [screenId, storeName] = key.split(".");
        if (screenId && storeName) {
          const existing = registryRef.current.get(screenId);
          if (existing && !existing.storeKeys.includes(storeName)) {
            registryRef.current.set(screenId, {
              ...existing,
              storeKeys: [...existing.storeKeys, storeName],
            });
          }
        }
        bump();
        return () => {
          storesRef.current.delete(key);
          if (screenId && storeName) {
            const existing = registryRef.current.get(screenId);
            if (existing) {
              registryRef.current.set(screenId, {
                ...existing,
                storeKeys: existing.storeKeys.filter((n) => n !== storeName),
              });
            }
          }
          bump();
        };
      },
    };
  }, [registryVersion]);

  return (
    <ScreenSystemContext.Provider value={value}>{children}</ScreenSystemContext.Provider>
  );
}

ScreenSystem.displayName = "ScreenSystem";

import { Field, Input } from "@particle-academy/react-fancy";
import type { SecurityTxtModel } from "../model.js";
import { validateSecurityTxt } from "../validate.js";
import { IssueList, Section, StringList } from "./internal.js";

export interface SecurityTxtEditorProps {
  value: SecurityTxtModel;
  onChange: (next: SecurityTxtModel) => void;
  hideIssues?: boolean;
  className?: string;
}

/**
 * Controlled security.txt editor (RFC 9116). Contact is required (one or more
 * mailto:/https: URIs) and Expires must be a future date — surfaced both as a
 * date input and inline issues from {@link validateSecurityTxt}.
 */
export function SecurityTxtEditor({
  value,
  onChange,
  hideIssues,
  className,
}: SecurityTxtEditorProps) {
  const issues = validateSecurityTxt(value);
  const patch = (next: Partial<SecurityTxtModel>) =>
    onChange({ ...value, ...next });

  // <input type="datetime-local"> wants `YYYY-MM-DDTHH:mm`; tolerate a stored
  // ISO string with seconds/zone by trimming to minutes for the control.
  const expiresLocal = value.expires ? value.expires.slice(0, 16) : "";

  return (
    <div className={className} data-x-editor="securityTxt">
      <Section title="Contact (required)" handle="security-contact">
        <StringList
          handle="security-contact"
          values={value.contact}
          onChange={(contact) => patch({ contact })}
          placeholder="mailto:security@example.com"
        />
      </Section>

      <Section title="Expires (required, future)" handle="security-expires">
        <Field description="Must be a date/time in the future.">
          <input
            type="datetime-local"
            value={expiresLocal}
            onChange={(e) =>
              patch({
                expires: e.target.value
                  ? `${e.target.value}:00Z`
                  : "",
              })
            }
            data-x-input="security-expires"
            style={{
              padding: "0.4rem 0.6rem",
              borderRadius: "0.4rem",
              border: "1px solid var(--rf-border, #e5e7eb)",
            }}
          />
        </Field>
      </Section>

      <Section title="Optional fields" handle="security-optional">
        <Input
          label="Encryption"
          value={value.encryption ?? ""}
          onValueChange={(v) => patch({ encryption: v || undefined })}
          placeholder="https://example.com/pgp-key.txt"
          data-x-input="security-encryption"
        />
        <Input
          label="Acknowledgments"
          value={value.acknowledgments ?? ""}
          onValueChange={(v) => patch({ acknowledgments: v || undefined })}
          placeholder="https://example.com/hall-of-fame"
          data-x-input="security-acknowledgments"
        />
        <Input
          label="Preferred-Languages"
          value={value.preferredLanguages ?? ""}
          onValueChange={(v) => patch({ preferredLanguages: v || undefined })}
          placeholder="en, fr"
          data-x-input="security-languages"
        />
        <Input
          label="Canonical"
          value={value.canonical ?? ""}
          onValueChange={(v) => patch({ canonical: v || undefined })}
          placeholder="https://example.com/.well-known/security.txt"
          data-x-input="security-canonical"
        />
        <Input
          label="Policy"
          value={value.policy ?? ""}
          onValueChange={(v) => patch({ policy: v || undefined })}
          placeholder="https://example.com/security-policy"
          data-x-input="security-policy"
        />
        <Input
          label="Hiring"
          value={value.hiring ?? ""}
          onValueChange={(v) => patch({ hiring: v || undefined })}
          placeholder="https://example.com/jobs"
          data-x-input="security-hiring"
        />
      </Section>

      {hideIssues ? null : <IssueList issues={issues} testid="securityTxt" />}
    </div>
  );
}

